(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-stage-serving-pipeline"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-1\">一 · 一次尾延迟雪崩：单体管线里被“绑架”的 VAE</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-2\">二 · 它精确解决的那一类问题：阶段异构 + 尾延迟约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-3\">三 · 它不解决什么：三类问题必须交给别的机制</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-4\">四 · 失败模式：latent 传输、冷启动与无背压的雪崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-5\">五 · 适用边界的量化判断：什么时候拆、什么时候不拆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-6\">六 · 阶段切分的收益边界：从一次 P99 雪崩说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-7\">七 · 网关入口与编码阶段的批量成形</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-8\">八 · 去噪池的分池取数与多步前向</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-9\">九 · 解码队列与 VAE 的 tile 并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-10\">十 · 阶段级背压与副本弹性的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-11\">十一 · 跨节点传输与队列缓冲的规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-12\">十二 · 阶段切分的边界：何时拆、何时不拆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-13\">十三 · 端到端时延公式的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-14\">十四 · SLO 约束与副本数的比例关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-15\">十五 · 背压的判据与丢弃策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-16\">十六 · 阶段异构与硬件档位的配比推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-17\">十七 · 量化按阶段选型对公式参数的影响</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-18\">十八 · 失败模式的公式化识别</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-19\">十九 · 阶段拆分的收益边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-20\">二十 · 请求形态决定拆分是否划算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-21\">二十一 · 并发与批大小的分段配方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-22\">二十二 · 负载不对时的三种失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-23\">二十三 · 配方参数的工程取值逻辑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-24\">二十四 · 适用边界的量化判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-25\">二十五 · 负载配方：混合分辨率、阶段独立批与背压边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-26\">二十六 · 硬件档位：按阶段画像选卡，而不是按整机峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-27\">二十七 · 并行拓扑：阶段内数据并行，阶段间流水</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-28\">二十八 · 量化方案：按阶段的数值敏感度分档</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-29\">二十九 · KV 与中间态策略：latent 队列的缓冲与生命周期</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-30\">三十 · 调度参数：副本弹性、优先级与降级路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-31\">三十一 · 可复现配置的落地顺序与验收口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-32\">三十二 · 端到端时延由最慢阶段钉住：把 max 拆成可观测的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-33\">三十三 · 显存：三阶段峰值不同步，副本弹性撞上碎片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-34\">三十四 · 带宽与通信：latent 过网是收益的隐形税</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-35\">三十五 · 功耗与利用率：空转被拆掉，但新空转在队列边界出现</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-36\">三十六 · 尾延迟与规模上限：先崩的是队列缓冲与调度器，不是 GPU</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-37\">三十七 · 规模化的工程判断：收益曲线在跨节点比例上升时掉头</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-38\">三十八 · 规模上去以后：先崩在跨节点 latent 搬运，再崩在调度器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-39\">三十九 · 精度漂移：三阶段各自失守的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-40\">四十 · OOM 的三条路径与队列背压</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-41\">四十一 · 批抖动与路由不均的耦合诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-42\">四十二 · 尾延迟尖刺的四个来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-43\">四十三 · 监控面与回滚的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-44\">四十四 · 阶段拆分的失效边界与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-45\">四十五 · 对照轴：切分维度与耦合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-46\">四十六 · 决策表：四类候选与适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-47\">四十七 · 副本弹性：容量公式与调度滞后</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-48\">四十八 · 量化与并行的阶段化选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-stage-serving-pipeline-sec-49\">四十九 · 失败模式的归属判断</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:514px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 514.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"432.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入网关，文本编码阶段批量编码 prompt 并写 latent 队列</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"432.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">去噪阶段按分辨率与步数分池，从队列取 latent 做多步 DiT 前向</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"432.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">去噪完成的 latent 进入解码队列，VAE 阶段按 tile 并行解码</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"432.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">各阶段暴露队列深度与 P99 时延，调度器按 SLO 扩缩副本</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"432.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">过载时按优先级丢弃或降分辨率，保证尾延迟</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-stage-serving-pipeline-sec-1\">一 · 一次尾延迟雪崩：单体管线里被“绑架”的 VAE</h3>\n<p>先看一个线上事故的形态。某文生图服务把文本编码、DiT 去噪、VAE 解码塞进同一个进程、同一组 GPU，请求以固定 batch 进入。白天流量平稳时 P99 尚可；一次活动流量突增后，网关侧看到的现象是：队列不长，但 P99 从可接受区间直接跳到数倍，超时请求集中在“已经去噪完成、等待出图”的那一批。根因不在去噪，而在解码：去噪阶段为了吞吐把 batch 拉到很大，这批 latent 一次性推进 VAE，VAE 的 tile 并行度是按单张小图调的，于是解码阶段瞬间吃掉数倍于平时的激活显存与算力，GPU 在解码上长时间饱和，而文本编码阶段的小 kernel 又在等待同一批 SM 资源，被拖成碎片化执行。整条管线没有阶段级隔离，一个阶段的批大小决策直接决定了另一个阶段的排队形态。</p>\n<p>这个事故的本质不是某个算子慢，而是三个阶段的资源特征被强行对齐：文本编码是低算力、小 kernel、对 launch 开销敏感；DiT 去噪是长时间、高算力、随分辨率与步数线性膨胀；VAE 解码是显存带宽与激活显存密集、并行粒度按 tile 走。单体部署下，GPU 在 VAE 阶段空转等待调度、在文本编码阶段被小 kernel 拖慢，SLO 抖动成为结构性现象而非偶发。阶段级扩散服务流水要解决的正是这个：把管线按数据流切成独立部署、独立 batch、独立弹性的三段，用 latent 队列解耦，让每个阶段按自己的资源曲线运行。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-2\">二 · 它精确解决的那一类问题：阶段异构 + 尾延迟约束</h3>\n<p>该算法的问题域可以写成一个带概率约束的优化：在给定到达率与请求形态混合下，让端到端时延满足</p>\n<div class=\"formula\">$$\\text{SLO}:\\ P\\big(T_{\\text{enc}}+T_{\\text{denoise}}+T_{\\text{dec}}\\le \\tau\\big)\\ge 1-\\epsilon,\\quad \\text{Replicas}_{s}\\propto\\frac{\\lambda_{s}\\,\\bar{t}_{s}}{\\text{target util}}$$</div>\n<p>其中三段时延的分布形状完全不同：编码段近似常量加小抖动，去噪段随步数与分辨率呈阶梯状，解码段受 tile 数与显存带宽支配。单体部署只能用一个 batch 策略同时服务三种分布，等价于用一个标量去拟合三条曲线，尾延迟必然被最慢那段拖走。阶段级流水把它拆成三个可独立整定的排队系统，端到端时延由最慢阶段决定：</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</div>\n<p>这里 $Q_k$ 是第 $k$ 阶段队列深度，$B_k$ 是该阶段批大小，$T_k^{\\mathrm{svc}}$ 是单批服务时间。公式给出的工程判断很直接：想让 $T_{\\mathrm{e2e}}$ 下降，要么压 $Q_k$（背压与副本弹性），要么压 $T_k^{\\mathrm{svc}}$（阶段内 batch 与并行策略），而这两件事在单体部署里是耦合的——调大去噪 batch 会同时抬高解码段的 $T_k^{\\mathrm{svc}}$，因为解码被迫处理更大的 latent 批次。拆开之后，去噪段按分辨率与步数分池，解码段按 tile 并行，两个 $T_k^{\\mathrm{svc}}$ 各自独立可调。</p>\n<p>具体例子：混合分辨率文生图请求流里，小图与大图的比例随时间漂移。单体部署下，大图请求会把整个 batch 的去噪时间拉长，连带小图请求的解码也被推迟；分阶段后，去噪段按分辨率分池，小图池与大图池各自成批，解码段按 tile 取 latent，小图请求不再被大图的解码批次绑架。整机吞吐在该配方下提升 1.5–2 倍，收益主要来自 VAE 不再被去噪 batch 绑架，以及编码段可以用大批把 launch 开销摊薄。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-3\">三 · 它不解决什么：三类问题必须交给别的机制</h3>\n<p>边界要划清楚，否则会把阶段切分当成万能药。第一，它不解决单阶段内部的算力效率问题。去噪段的多步 DiT 前向若受限于注意力实现或数值精度，切分阶段不会让单步变快——那属于 Blackwell 异步 FA3 注意力、tcgen05/TMEM 的 MMA 路径、NVFP4/FP8 量化等条目的话题，本算法只负责让这些优化在正确的批形态下运行。第二，它不解决请求到达侧的异构。连续批处理解决的是“请求在不同时刻到达、长度不一”的调度问题，阶段级流水解决的是“同一请求在管线不同段上资源需求不同”的问题，两者互补而非替代；把阶段切分当作连续批处理的替代品，会在到达抖动时暴露队列积压。第三，它不解决空间切分问题。patch 级调度、混合分辨率补丁调度是按空间维度切分计算，阶段级流水是按管线维度切分，二者正交；高分辨率下单张图的解码仍要靠 VAE 分块并行解码来压显存峰值。</p>\n<p>还有一个容易误判的边界：小规模单卡部署下拆分收益有限。三阶段独立部署意味着至少三份模型驻留与三套队列缓冲，单卡上这些开销直接吃掉隔离带来的收益；当阶段数增多、跨节点传输增多时，latent 传输的显存拷贝与网络开销会侵蚀吞吐收益，尤其在高分辨率 latent 下更明显。规模上限受队列缓冲容量与调度器容量约束，不是无限可扩。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-4\">四 · 失败模式：latent 传输、冷启动与无背压的雪崩</h3>\n<p>拆开之后新增的代价集中在阶段间边界。latent 队列不是零成本：每次跨阶段传递要做显存拷贝，跨节点时还要走网络，高分辨率 latent 的体积让这笔开销不可忽略。工程上的判断是，同节点内用显存队列、跨节点才走网络传输，并且队列深度要设上限——队列本身就是缓冲区，深度越深，尾延迟的方差越大。第二个失败模式是多副本弹性：扩缩容引发冷启动与显存碎片，调度器在负载突增时可能做出滞后决策，副本还没起来、旧副本已经按低水位缩掉，直接导致 SLO 违约。第三个失败模式最危险：队列积压缺乏背压时，上游阶段持续灌入，下游 OOM 或长尾请求堆积，形成雪崩。事故里“队列不长但 P99 爆炸”正是背压缺失的典型形态——队列深度指标没爆，但下游服务时间已经失控。</p>\n<p>对应的机制是阶段级背压：各阶段暴露队列深度与 P99 时延，调度器按 SLO 扩缩副本；过载时按优先级丢弃或降分辨率，保证尾延迟。这里的伪代码思路是，网关在入队前检查下游队列水位与预测服务时间，超过阈值就触发降级而非继续灌入；降分辨率是比丢弃更平滑的手段，因为它把 $T_k^{\\mathrm{svc}}$ 直接压下来，而不是让请求消失。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-5\">五 · 适用边界的量化判断：什么时候拆、什么时候不拆</h3>\n<p>把适用性写成可核对的判据，而不是感觉。第一条判据是阶段资源曲线的分离度：若三段的最优 batch 大小相差一个数量级以上、或显存峰值相差显著，拆分收益明确；若三段特征接近，拆分只增加传输开销。第二条判据是跨节点比例：阶段间传输若全在同节点，拷贝开销可控；一旦跨节点比例上升，网络开销按 latent 体积线性增长，收益被侵蚀。第三条判据是规模：单卡或极少副本时，三份模型驻留与三套队列缓冲的固定成本占比过高，拆分不划算；多副本、多阶段的长管线才是目标场景。</p>\n<p>部署配方上，硬件档位可按阶段异构：编码用低算力卡、去噪用高算力卡、解码用大显存卡；并行拓扑为阶段内数据并行加阶段间流水；量化按阶段选 FP8/NVFP4。这套异构配置只有在阶段独立部署时才成立，单体部署被迫用同一档硬件服务三种曲线，这正是它空转与拖慢的来源。最后落在工程判断上：阶段级流水的价值不在“拆”这个动作本身，而在于把 SLO 约束从一条不可分解的端到端曲线，变成三条可分别整定的阶段曲线，并用背压把最慢阶段的水位钉在阈值以下；一旦跨节点传输开销或调度器滞后超过这条收益线，就该退回更粗的切分粒度，而不是继续加阶段。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-6\">六 · 阶段切分的收益边界：从一次 P99 雪崩说起</h3>\n<p>某线上文生图服务在单体部署下遇到过一次典型的尾延迟事故：白天流量平稳时 P99 尚可接受，但每到混合分辨率请求集中到达的时段，网关侧 P99 便出现数倍于基线的尖峰，而 GPU 利用率曲线却呈现出规律的锯齿——高算力区间与近乎空转的区间交替出现。根因不在某一阶段算得慢，而在三个阶段被绑在同一执行序列里：文本编码阶段的小 kernel 无法填满 SM，去噪阶段的大 batch 又把 VAE 解码挤到队尾，VAE 阶段按 tile 展开时前面的去噪 batch 仍占着显存无法释放，于是整机在“编码等待—去噪拥塞—解码空转”之间反复摆动。用端到端时延的分解式看，问题一目了然：</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</div>\n<p>单体部署等价于把三个 $k$ 强行串成一条链，任一阶段的 $Q_k/\\lambda_k$ 膨胀都会直接抬高端到端时延，而其他阶段的算力却无法挪用过来削峰。阶段级扩散服务流水解决的正是这个具体问题：把编码、去噪、解码拆成独立部署的副本组，各自按阶段特征设定批大小与并行拓扑，阶段间用 latent 队列解耦成异步流水，再以队列深度与 P99 时延为信号做背压与副本弹性。它换来的是各阶段独立 batch 后整机吞吐 1.5–2 倍的提升，以及尾延迟从“被最慢阶段绑架”变为“由最慢阶段可观测、可扩缩”的可控状态。但它不解决请求到达侧的异构性——连续批处理负责的是同一阶段内不同长度请求的拼批效率，两者互补而非替代；它也不解决单卡小规模部署的算力碎片问题，把一条本已紧凑的管线切成三段，反而会让每段都吃不饱。</p>\n<p>失效条件集中在三处，且都与“切分带来的额外开销”直接相关。其一是阶段间 latent 传输：每次跨阶段交接都要做一次显存拷贝，跨节点时还要走网络，高分辨率 latent 下这笔开销会显著侵蚀吞吐收益，当通信时间与阶段服务时间同量级时，拆分反而劣于单体。其二是多副本弹性的冷启动与显存碎片：调度器依据 $Q_k$ 与 P99 扩缩副本，但新副本拉起需要加载权重、预热 kernel，负载突增时决策滞后会让 SLO 在扩容完成前就已违约。其三是缺少背压的队列积压：上游编码阶段持续灌入而下游 VAE 吞吐不足时，latent 队列会一路涨到显存上限，触发 OOM 或让长尾请求无限排队。因此适用边界可以写得很硬：阶段资源需求差异越大、管线越长、单副本算力越富裕，拆分收益越明显；反之，阶段数增多导致跨节点传输占比上升，规模上限被队列缓冲容量与调度器决策频率共同约束。工程判断上，先测量各阶段 $T_k^{\\mathrm{svc}}$ 与 $Q_k/\\lambda_k$ 的比值，只有当某一阶段的排队项稳定主导端到端时延、且该阶段资源画像与其他阶段显著不同时，切分才值得付出那笔 latent 拷贝与调度复杂度。</p>\n<table class=\"mini\"><thead><tr><th>场景特征</th><th>拆分收益</th><th>主要代价来源</th></tr></thead><tbody><tr><td>多分辨率混合、三阶段资源画像差异大</td><td>吞吐 1.5–2 倍，P99 可控</td><td>latent 拷贝、跨节点网络</td></tr><tr><td>单一分辨率、请求形态均一</td><td>有限，批处理已足够</td><td>调度器复杂度、冷启动</td></tr><tr><td>小规模单卡部署</td><td>负收益，各段吃不饱</td><td>显存碎片、副本空转</td></tr></tbody></table>\n<h3 id=\"alg-stage-serving-pipeline-sec-7\">七 · 网关入口与编码阶段的批量成形</h3>\n<p>请求从网关进入时，携带的是 prompt 文本、目标分辨率、采样步数与优先级标签。网关做的第一件事不是立刻转发，而是把请求写入一个按优先级分层的准入队列，并按分辨率与步数打上路由键——这个键决定它后续进入哪一个去噪池。网关的代价是纯 CPU 与内存的：它不占 GPU，但必须维持足够深的准入缓冲，否则突发流量会直接击穿编码阶段的批处理窗口。工程上常把网关与文本编码阶段放在同一节点，用共享内存传递 tokenized 输入，省掉一次跨进程拷贝。</p>\n<p>文本编码阶段的输入是 token id 序列，输出是条件 latent（以及 CFG 所需的负向条件，若走合并批则一并编码）。这一阶段的算力特征是小 kernel 主导：编码器前向的矩阵乘维度受限于序列长度与隐藏维，单请求的 kernel 发射开销占比高，GPU 利用率被拖在低位。因此它的批策略与去噪阶段相反——追求大批、长驻留，把多个请求的 token 序列 padding 到同一长度后一次前向。代价体现在显存上：padding 浪费的激活显存随批内最长序列线性增长，批越大浪费越多；同时也体现在延迟上，一个请求要等批凑满或等超时窗口到期才能被编码，这部分排队时间直接计入端到端时延。</p>\n<p>编码完成的 latent 被写入 latent 队列，这是阶段解耦的第一个物理落点。队列元素不只是张量，还带元数据：分辨率、剩余步数、优先级、入队时间戳。队列本身消耗显存或主机内存，跨节点时消耗网络缓冲。写队列的动作是一次显存拷贝，读队列是另一次——这两次拷贝在单节点内可忽略，跨节点时就是实打实的 RDMA 往返。用公式刻画端到端时延的下界：</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</div>\n<p>其中 $Q_k$ 是第 $k$ 阶段队列深度，$\\lambda_k$ 是该阶段吞吐，$B_k$ 为批大小，$T_k^{\\mathrm{svc}}$ 为单批服务时间。这个式子说明一件事：端到端时延由最慢阶段决定，而最慢阶段往往是队列深度除以吞吐最大的那个。编码阶段若批太小，$\\lambda_k$ 上不去，$Q_k/\\lambda_k$ 就会膨胀，即使它的 $T_k^{\\mathrm{svc}}$ 很短，也会成为瓶颈。举例：混合分辨率文生图负载下，编码阶段设大批、去噪阶段按分辨率分池，若编码批被超时窗口截断而未能凑满，队列会在去噪池入口堆积，此时扩容编码副本比扩容去噪副本更有效——这正是阶段级可观测性带来的判断力。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-8\">八 · 去噪池的分池取数与多步前向</h3>\n<p>去噪阶段从 latent 队列取数，但取数不是无差别的。调度器按分辨率与步数把去噪副本划成若干池：低分辨率短步数池、高分辨率长步数池，各自独立批处理。分池的理由是显存与算力特征随分辨率剧烈变化——高分辨率 latent 的激活显存与注意力计算量远大于低分辨率，混批会让大批被小请求拖住、小批被大请求撑爆显存。分池的代价是碎片化：每个池要预留自己的批缓冲与 KV 式中间缓存，池越多，显存利用率越难打满，低负载时某些池空转。</p>\n<p>取数之后是多步 DiT 前向。输入是带噪 latent、条件嵌入、当前步索引与调度器系数，输出是去噪一步后的 latent，循环直到步数耗尽。这一步的代价结构最重：每步都要做一次完整的前向，注意力与 GEMM 交替，显存带宽与算力同时吃紧。批内请求步数若不一致，就得按最大步数对齐，短步数请求在前向中被空转——这是去噪池按步数分池的直接动机。伪代码思路如下：</p>\n<div class=\"formula\">$$\\text{for } s \\text{ in } 0..S-1:\\ \\ x \\leftarrow \\mathrm{DiT}(x, c, s);\\ \\ \\text{if } s \\equiv 0 \\pmod{m}:\\ \\text{checkpoint}(x)$$</div>\n<p>其中 checkpoint 的间隔 $m$ 是显存与重算的权衡：存得越密，显存占用越高；存得越疏，中断恢复要重算的步数越多。去噪阶段的吞吐由批大小与单步时间共同决定，而单步时间又被分辨率与是否启用低精度路径左右。工程判断是：去噪池的批大小不应跨分辨率统一设定，否则高分辨率池会因显存不足被迫减小批，吞吐掉下来，$Q_k/\\lambda_k$ 上升，尾延迟恶化。一个具体例子：同一副本上若把 1024 与 512 分辨率混在一批，1024 的激活显存决定了批上限，512 请求只能陪跑，整池吞吐被拉低到接近纯 1024 池的水平，而 512 请求的排队时间白白增加。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-9\">九 · 解码队列与 VAE 的 tile 并行</h3>\n<p>去噪完成的 latent 进入解码队列，这是第二个解耦点。队列元素此时已无步数概念，只剩分辨率与优先级。VAE 解码阶段的输入是干净 latent，输出是像素张量。它的算力特征与去噪相反：卷积为主、访存密集、对显存容量敏感——高分辨率输出的像素张量体量远超 latent，单张图就可能吃掉数 GB 显存。因此解码阶段按 tile 并行：把输出图切成若干块，每块独立解码再拼接，块间在边界处需要重叠像素以避免接缝。tile 并行的代价是重复计算边界区域，tile 越小重复越多，总算力上升；tile 越大并行度越低，单卡显存压力越大。</p>\n<p>解码阶段最怕的是被去噪批绑架。单体部署时，VAE 必须等整个去噪批完成才能启动，批内最慢请求决定解码开始时刻，GPU 在等待期间空转。拆阶段后，解码队列可以按到达顺序逐个消费，先完成的 latent 先解码，GPU 不再空转。代价是解码副本要独立配置显存：大显存卡用于高分辨率 tile 解码，低算力卡解码小图。这里有一个显存碎片问题——tile 缓冲按最大 tile 预留，小图请求进来时缓冲浪费，多副本弹性扩缩时这些预留块难以回收，形成碎片。工程上常用固定 tile 尺寸加动态批来缓解，但固定尺寸又牺牲了小图的解码效率。</p>\n<p>解码阶段的吞吐受限于显存带宽而非算力，因此它的副本数不必与去噪副本同比例扩张。举例：去噪池扩容一倍时，解码队列深度可能只上升少许，因为解码单批服务时间短、批间切换快；此时盲目扩容解码副本只会增加冷启动开销与显存碎片，而不改善端到端时延。判断依据是各阶段暴露的 P99 时延与队列深度：若解码 P99 平稳而队列深度低，说明瓶颈不在解码。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-10\">十 · 阶段级背压与副本弹性的耦合</h3>\n<p>三个阶段的队列深度与 P99 时延被持续暴露给调度器。调度器按 SLO 做扩缩：某阶段队列深度持续超过阈值且 P99 逼近目标，就扩副本；队列清空且 P99 远低于目标，就缩副本。副本数的粗略比例关系是：</p>\n<div class=\"formula\">$$\\text{Replicas}_{s}\\propto\\frac{\\lambda_{s}\\,\\bar{t}_{s}}{\\text{target util}}$$</div>\n<p>其中 $\\lambda_s$ 是该阶段到达率，$\\bar{t}_s$ 是平均服务时间。这个式子给出的是稳态下的比例，但弹性扩缩的代价在于它不稳态：冷启动要加载权重、初始化显存池、预热 kernel，这段时间内新副本不产出，队列继续积压。更糟的是缩容时的显存碎片——副本退出后释放的显存块大小不一，新副本申请大块时可能失败，调度器被迫做整理或等待，决策滞后。</p>\n<p>背压是防止雪崩的闸门。当解码队列深度超过上限，背压信号回传给去噪池，去噪池停止从 latent 队列取数；latent 队列满后，编码阶段停止编码，网关开始按优先级丢弃或降分辨率。降分辨率是一个有损但可控的过载策略：把高分辨率请求降到低分辨率池处理，牺牲质量保尾延迟。优先级丢弃则更激进，直接拒绝低优先级请求并返回可重试信号。两者的代价不同：降分辨率增加低分辨率池的负载，可能把瓶颈转移到那里；丢弃则损失吞吐但保住 SLO 达标率。工程判断是，过载时先降分辨率、后丢弃，因为降分辨率仍产出可用结果，而丢弃是纯损失。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-11\">十一 · 跨节点传输与队列缓冲的规模上限</h3>\n<p>阶段间 latent 传输在单节点内是显存拷贝，跨节点时是网络传输。高分辨率 latent 的体量随分辨率平方增长，跨节点传输的带宽开销可能吃掉拆分带来的吞吐收益。这是规模上限的第一道约束：阶段数越多、跨节点链路越多，通信开销侵蚀越明显。缓解手段是把相邻阶段放在同一节点或同一 NVLink 域内，只把跨域的那一段留给网络；或者压缩 latent 再传，代价是编解码算力与精度损失。</p>\n<p>第二道约束是队列缓冲容量。队列太浅，突发流量直接击穿背压，上游被迫停摆；队列太深，积压的 latent 占用显存与网络缓冲，且长尾请求在队列里等待的时间计入端到端时延。队列深度应按 SLO 反推：给定目标 P99 与阶段吞吐，队列深度上限约等于 $\\lambda_k \\cdot (\\tau - T_k^{\\mathrm{svc}})$，超过这个值的积压注定违约，不如提前丢弃。这个反推把队列从被动缓冲变成主动准入控制点。</p>\n<p>第三道约束是调度器容量。副本数、池数、优先级层数三者相乘构成调度状态空间，状态越多，调度决策的滞后越明显。负载突增时，调度器若还在按上一周期的队列深度做决策，扩出来的副本可能已经错过峰值。工程上把调度周期压到秒级、把扩缩阈值设成滞回区间，能减少抖动，但代价是响应变慢。一个具体例子：三阶段各两副本、每阶段三个优先级层，状态空间已不小；若再把去噪池按分辨率细分成四池，调度器要在十几个维度上同时决策，滞后风险显著上升。此时宁可减少池数、用批内对齐吸收分辨率差异，也不要把调度器撑爆。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-12\">十二 · 阶段切分的边界：何时拆、何时不拆</h3>\n<p>三阶段独立部署的收益并非无条件成立，其边界由通信项与调度粒度共同决定。端到端时延由最慢阶段主导：<div class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</div>拆分后每阶段可独立设定 $B_k$，但阶段间 latent 需经显存拷贝与队列传输，跨节点时该项直接叠加进 $T_k^{\\mathrm{svc}}$。高分辨率 latent 体积随像素线性增长，传输开销会侵蚀 1.5–2 倍的吞吐收益；当单卡即可容纳全管线、且请求到达平稳时，拆分的调度与拷贝成本超过收益，此时应退回单体部署。阶段数越多、跨节点链路越多，收益衰减越快。</p>\n<p>失效条件集中在三类。其一，队列无背压：上游编码阶段以大批量持续灌入，去噪池消费不足时 $Q_k$ 单调上升，下游 OOM 或长尾堆积，尾延迟失控——必须以队列深度阈值触发上游限流或降分辨率，而非等 P99 报警后再扩副本。其二，弹性滞后：副本扩缩存在冷启动与显存碎片，负载突增时调度器决策落后于到达率变化，SLO 违约发生在扩容完成之前，故需预留最小热副本并配合优先级丢弃。其三，分池粒度失配：去噪按分辨率与步数分池后，小池副本利用率低，若按 $\\text{Replicas}_{s}\\propto\\lambda_{s}\\bar{t}_{s}/\\text{target util}$ 逐池配置，碎片化显存会压缩可用 batch 上限。</p>\n<p>系统代价需按阶段异构核算：编码阶段小 kernel 拖慢，宜用低算力卡配大批；去噪阶段吃算力与 TMEM，配高算力卡；解码阶段按 tile 并行、吃显存带宽，配大显存卡。跨节点 latent 队列还需网络缓冲，其容量直接约束规模上限。工程判断是：先测单请求三阶段服务时间占比，若解码与编码合计占比低且方差小，拆分收益有限；反之若 VAE 空转明显、P99 抖动来自阶段间 batch 绑架，则拆分并用队列深度做背压是必要手段。</p>\n<h3 id=\"alg-stage-serving-pipeline-sec-13\">十三 · 端到端时延公式的逐项拆解</h3>\n<p>阶段级流水把扩散服务看成一条串联的排队网络：编码、去噪、解码三段各自有队列与服务台。核心公式写成</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</div>\n<p>逐项看：$Q_k$ 是第 $k$ 阶段在取批时刻的队列深度（以请求为单位），$\\lambda_k$ 是该阶段在稳态下的吞吐（请求/秒），$T_k^{\\mathrm{svc}}$ 是一批请求从进入到离开该阶段的服务时间。括号内两项含义不同——$Q_k/\\lambda_k$ 是排队等待项，$T_k^{\\mathrm{svc}}$ 是服务项。外层取 max 而不是求和，是这条公式最关键的推导一步：三段之间由 latent 队列解耦、异步推进，请求在阶段 $k$ 排队时，阶段 $k+1$ 正在处理更早的请求，因此各阶段的时延在流水意义上重叠，端到端时延由**最慢的那一段**决定，而非三段之和。若写成求和，就等于假设三段严格串行、无重叠，那正是单体部署的模型，拆分收益被完全抹掉。</p>\n<p>把 $\\lambda_k$ 代入可得到更实用的形式：$Q_k/\\lambda_k = Q_k T_k^{\\mathrm{svc}}/B_k$，即排队项正比于队列深度与单批服务时间、反比于批大小。这解释了为什么编码阶段要大批：它的 $T_k^{\\mathrm{svc}}$ 被小 kernel 拖长，增大 $B_k$ 能摊薄单位请求的服务成本，同时压住排队项。代价是编码阶段的大批会让该阶段的服务项变长，若 $B_k$ 过大，$T_k^{\\mathrm{svc}}$ 反而成为 max 的取值者。工程判断是：批大小应按“使各阶段的 $\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}$ 尽量相等”来配，而不是各阶段都往最大批推。</p>\n<p>具体例子：混合分辨率文生图请求流下，编码阶段用大批、去噪阶段按分辨率分池、VAE 阶段按 tile 并行。若解码阶段 tile 并行度不足，$T_{\\text{dec}}^{\\mathrm{svc}}$ 抬高，即使前两段队列为空，端到端 P99 仍被解码段钉住——这正是单体部署中“VAE 阶段 GPU 空转”的另一种表现，只不过在拆分后它变成了可观测、可单独扩容的一段。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-14\">十四 · SLO 约束与副本数的比例关系</h3>\n<p>服务等级写成概率约束：</p>\n<div class=\"formula\">$$\\text{SLO}:\\ P\\big(T_{\\text{enc}}+T_{\\text{denoise}}+T_{\\text{dec}}\\le \\tau\\big)\\ge 1-\\epsilon,\\quad \\text{Replicas}_{s}\\propto\\frac{\\lambda_{s}\\,\\bar{t}_{s}}{\\text{target util}}$$</div>\n<p>左式的三项之和是**单请求视角**的时延分解，与第一节的 max 形式并不矛盾：max 描述的是系统稳态下流水重叠后的端到端时延，而单请求实际经历的墙钟时间仍是三段各自耗时之和（减去它在队列中被前序请求挡住的部分）。做 SLO 达标率统计时必须用单请求视角，否则会把流水重叠误算成时延缩短。$\\epsilon$ 是允许的违约比例，P99 尾延迟对应 $\\epsilon=0.01$ 量级的目标。</p>\n<p>右式的推导关键一步是利特尔法则（Little's Law）：稳态下在制请求数 $L_s=\\lambda_s\\bar{t}_s$，其中 $\\bar{t}_s$ 是该阶段平均驻留时间（排队加服务）。若要求每个副本的目标利用率为 $\\text{target util}$（即副本繁忙时间占比），则单副本能承载的在制请求数为 $\\text{target util}$，副本数即为 $L_s/\\text{target util}$。利用率不取 1 是刻意的：排队时延随利用率非线性上升，$\\text{target util}$ 留出的余量正是尾延迟的缓冲。这也解释了为什么按平均吞吐配副本会在突发时违约——$\\lambda_s$ 是均值，而 P99 由方差驱动。</p>\n<p>系统代价在这里体现为弹性成本：副本数按上式扩缩，多副本带来冷启动与显存碎片，调度器复杂度上升。具体例子：去噪阶段按分辨率分池后，高分辨率池的 $\\bar{t}_s$ 显著高于低分辨率池，两池的副本数必须分别按各自 $\\lambda_s\\bar{t}_s$ 计算，混算会让高分辨率池长期欠配、低分辨率池长期过配。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-15\">十五 · 背压的判据与丢弃策略</h3>\n<p>队列解耦的代价是积压可以在阶段间累积。背压需要一个可判定的触发条件，而不是凭队列深度拍脑袋。取第 $k$ 阶段队列的到达率 $\\lambda_k^{\\mathrm{in}}$ 与服务率 $\\lambda_k$，定义利用率 $\\rho_k=\\lambda_k^{\\mathrm{in}}/\\lambda_k$。当 $\\rho_k\\ge 1$ 时队列无界增长，必须在上游限流；工程上更早的触发点是按 P99 时延反推：若当前 $Q_k$ 使得 $\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}$ 已逼近 $\\tau$ 减去下游剩余预算，则停止向上游取新请求。</p>\n<p>伪代码落到可实现，核心是网关侧的准入与阶段侧的取批两个循环：</p>\n<ul>\n<li>网关：对每个新请求计算优先级与预估分辨率档位，读取消码阶段队列深度与 P99；若 $\\frac{Q_{\\text{dec}}}{\\lambda_{\\text{dec}}}$ 超过预算，则按优先级丢弃低优先级请求，或把请求降分辨率后重新入队。</li>\n<li>编码阶段：以固定时间窗聚合请求，凑满 $B_{\\text{enc}}$ 或超时即发；编码结果连同元数据（分辨率、步数、优先级）写入 latent 队列，写队列前检查队列水位，超水位则阻塞而非丢弃。</li>\n<li>去噪阶段：按分辨率与步数分池，每池独立取批；取批时读取本池 $Q_k$ 与 $\\lambda_k$，若预测本批完成时刻将超出该请求的 SLO 预算，则将该请求回退到队列头部等待下一轮。</li>\n<li>解码阶段：按 tile 并行解码，tile 数与显存预算绑定；解码队列水位过高时向去噪阶段发背压信号，去噪阶段降低取批速率。</li>\n</ul>\n<p>代价是背压信号本身要走网络，跨节点时延迟不可忽略；丢弃策略则直接损失吞吐。具体例子：过载时按优先级丢弃或降分辨率，是把“违约”从全体请求转移到低优先级请求上，保证尾延迟指标不被长尾拖垮——这是用可控的吞吐损失换 SLO 达标率。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-16\">十六 · 阶段异构与硬件档位的配比推导</h3>\n<p>三阶段算力与显存特征差异大，硬件档位可按阶段异构：编码用低算力卡、去噪用高算力卡、解码用大显存卡。配比推导的起点是各阶段的资源瓶颈不同。编码阶段被小 kernel 拖慢，瓶颈在 kernel 发射与调度而非浮点吞吐，因此低算力卡配大批即可饱和；去噪阶段是多步 DiT 前向，瓶颈在 tensor core 吞吐与显存带宽，需要高算力卡；解码阶段按 tile 并行，瓶颈在显存容量与带宽（tile 缓冲与特征图驻留），需要大显存卡。</p>\n<p>设三阶段的单请求资源消耗分别为 $r_{\\text{enc}},r_{\\text{den}},r_{\\text{dec}}$（以对应瓶颈资源计），则副本配比应满足 $\\text{Replicas}_{\\text{enc}}:\\text{Replicas}_{\\text{den}}:\\text{Replicas}_{\\text{dec}} \\approx \\lambda_{\\text{enc}}\\bar{t}_{\\text{enc}}:\\lambda_{\\text{den}}\\bar{t}_{\\text{den}}:\\lambda_{\\text{dec}}\\bar{t}_{\\text{dec}}$，再按各档位硬件的单副本容量折算成机器数。关键一步是：由于流水稳态下三段的吞吐必须相等（否则积压），$\\lambda_{\\text{enc}}=\\lambda_{\\text{den}}=\\lambda_{\\text{dec}}=\\lambda$，配比简化为 $\\bar{t}_{\\text{enc}}:\\bar{t}_{\\text{den}}:\\bar{t}_{\\text{dec}}$——即副本数正比于各阶段平均驻留时间。这给出一个可操作的判断：哪一段 $\\bar{t}$ 最长，就该给它最多的副本或最强的卡。</p>\n<p>代价是异构部署让显存碎片与冷启动问题更复杂：不同档位卡的显存容量不同，副本迁移与缩容时的碎片回收策略要分档设计。具体例子：解码阶段用大显存卡并按 tile 并行，若 tile 数按显存上限配置，缩容时释放的显存是离散的 tile 块而非整卡，调度器需要感知这种粒度才能有效复用。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-17\">十七 · 量化按阶段选型对公式参数的影响</h3>\n<p>量化按阶段选 FP8/NVFP4，直接改变公式里的 $T_k^{\\mathrm{svc}}$ 与 $\\lambda_k$，但对三段的影响不对称。去噪阶段是 GEMM 密集型，NVFP4 降低权重与激活位宽后 tensor core 吞吐上升，$T_{\\text{den}}^{\\mathrm{svc}}$ 下降、$\\lambda_{\\text{den}}$ 上升，该段从 max 的取值者位置上退出；解码阶段是访存密集型，量化主要降低显存带宽压力而非算力，$T_{\\text{dec}}^{\\mathrm{svc}}$ 的改善来自 tile 缓冲变小、驻留压力下降；编码阶段 kernel 小，量化收益被发射开销稀释，甚至可能因反量化引入额外指令而变慢。</p>\n<p>推导上，把 $\\lambda_k=B_k/T_k^{\\mathrm{svc}}$ 对 $T_k^{\\mathrm{svc}}$ 求偏导可知，$\\lambda_k$ 的相对提升等于 $T_k^{\\mathrm{svc}}$ 的相对下降；因此量化选型应优先投向当前 max 取值的那一段，而不是三段统一量化。这与“DiT NVFP4 混合精度量化”条目讲的逐层敏感度分析是不同层面的问题：那里决定层内哪些张量量化，这里决定阶段间把有限的量化工程投给谁。</p>\n<p>代价是混合精度让阶段间的数值一致性需要校验：编码输出的 latent 与解码输入的 latent 若精度档位不同，需明确转换点与舍入策略，否则误差在流水上累积。具体例子：去噪用 NVFP4、解码用 FP8 时，latent 队列中存的张量精度应由队列协议固定，避免每个消费者各自转换带来的重复开销与不一致。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-18\">十八 · 失败模式的公式化识别</h3>\n<p>三类失败模式都能在公式里找到对应项。第一类，跨节点 latent 传输的显存拷贝与网络开销吃掉吞吐收益：这体现为 $T_k^{\\mathrm{svc}}$ 中新增的传输项，高分辨率 latent 下该项随张量尺寸线性增长，使 $\\lambda_k$ 下降、$Q_k/\\lambda_k$ 上升，max 的取值者可能从计算段切换到传输段。识别方法是把传输时间单列为一项，观察它在 $T_k^{\\mathrm{svc}}$ 中的占比是否随分辨率档位上升而越过阈值。</p>\n<p>第二类，多副本弹性扩缩引发冷启动与显存碎片，调度器在负载突增时滞后决策导致 SLO 违约：这对应 $\\text{Replicas}_s$ 的调整滞后于 $\\lambda_s$ 的变化，在公式上表现为 $\\lambda_s$ 已上升而副本数仍按旧值，$\\rho_s$ 越过 1，$Q_s$ 无界增长。缓解手段是提前按预测负载预扩，而非等 P99 越线再扩。</p>\n<p>第三类，队列积压缺乏背压时上游持续灌入造成下游 OOM 或长尾堆积：这对应 $\\rho_k\\ge 1$ 且无准入控制，$Q_k$ 增长直到缓冲耗尽。具体例子：解码队列在水位超限时若只告警不限流，去噪阶段继续以满批写入，解码段的 tile 缓冲与 latent 队列同时吃显存，最终 OOM 而非优雅降级。工程判断是背压必须做成阻塞式而非告警式，且阻塞点应放在写入侧而非读取侧，因为读取侧的阻塞只会让上游队列继续膨胀。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-19\">十九 · 阶段拆分的收益边界与失效条件</h3>\n<p>阶段级流水把端到端时延压成瓶颈阶段的服务时间，但这条公式只在稳态下成立：<span class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</span>其中 $Q_k/\\lambda_k$ 是排队项。拆分收益来自各阶段独立设定 $B_k$——编码阶段大批摊薄小 kernel 开销、VAE 阶段按 tile 并行不再被去噪 batch 绑架，从而把单体部署里 VAE 空转与编码拖慢的损失收回，整机吞吐提升 1.5–2 倍。但排队项对 $Q_k$ 是线性的：一旦某阶段 $\\lambda_k$ 因分辨率分池或 tile 并行度不足而下降，$Q_k$ 迅速累积，$\\max_k$ 立刻转移到该阶段，拆分带来的并行度被排队延迟吃掉。换言之，拆分把“单体里的平均空转”换成了“跨阶段的尾部排队”，收益只在各阶段容量配比接近负载配方时兑现。</p>\n<p>第一个失效条件是跨节点 latent 传输。阶段间 latent 队列解耦了 batch，却也引入额外显存拷贝与网络开销；跨节点时更明显，高分辨率 latent 下拷贝量随空间尺寸增长，通信开销可能侵蚀吞吐收益。工程判断是：编码与去噪尽量同节点放置，只把 VAE 解码外移；latent 队列缓冲按“在途批次数 × 单批 latent 字节”预留显存与网络缓冲，缓冲不足时背压先于 OOM 触发。第二个失效条件是弹性副本的冷启动与显存碎片：调度器按队列深度与 P99 时延扩缩副本，但负载突增时决策滞后，新副本尚未预热，旧副本已积压，SLO 违约发生在扩容生效之前。第三个是缺背压的雪崩：上游持续灌入而下游 OOM，长尾请求堆积，此时按优先级丢弃或降分辨率是唯一止血手段，代价是达标率让位于尾延迟。</p>\n<p>规模上限由队列缓冲与调度器容量共同约束：阶段数越多、跨节点传输越多，收益被通信开销侵蚀；小规模单卡部署下拆分收益有限，因为阶段间同步与拷贝的固定开销占比过高。与连续批处理互补——后者解决请求到达的异构，前者解决阶段资源的异构，两者叠加时需注意批大小按阶段独立设定会让队列深度指标失去可比性，调度器应以各阶段 P99 服务时间而非队列长度作为扩缩主信号。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发信号</th><th>系统代价</th></tr></thead><tbody><tr><td>跨节点 latent 传输</td><td>解码阶段 P99 抬升、网络缓冲打满</td><td>显存拷贝与网络开销侵蚀吞吐</td></tr><tr><td>弹性滞后</td><td>扩容未生效前队列已积压</td><td>冷启动与显存碎片、SLO 违约</td></tr><tr><td>缺背压</td><td>下游 OOM、长尾堆积</td><td>丢弃或降分辨率，达标率下降</td></tr></tbody></table>\n<h3 id=\"alg-stage-serving-pipeline-sec-20\">二十 · 请求形态决定拆分是否划算</h3>\n<p>阶段级流水不是对所有扩散服务都成立。它的收益来自“三阶段资源画像彼此错位”这一事实：文本编码是极短序列上的小 kernel 密集区，DiT 去噪是长时、算力与显存带宽双饱和的多步前向，VAE 解码则是大分辨率张量上的分块卷积与上采样，显存占用高但算力利用率低。若请求形态使这三段在同一条时间轴上高度重叠，拆分才有意义；若请求本身就是单一分辨率、单一 prompt 长度、低并发，三段在单体部署里已经天然串行且互不干扰，拆开只会多出两次 latent 跨进程拷贝和一套队列管理。</p>\n<p>因此负载配方首先要回答的是“请求是否足够异质”。混合分辨率文生图是最典型的适配形态：同一批请求里既有低分辨率快出图，也有高分辨率慢出图，去噪阶段的步数与 latent 尺寸随分辨率变化，而编码阶段的 prompt 长度分布相对稳定。这种异质性让“按分辨率与步数分池”的去噪调度有实际对象可分，也让编码阶段的大批与小 kernel 拖慢问题暴露出来。反过来，若全部请求都是同一分辨率、同一采样步数、prompt 长度集中，去噪池退化成一个，阶段拆分的调度自由度归零，收益只剩 VAE 与去噪的解耦，而这一项在单卡上往往被 latent 拷贝开销抵消。</p>\n<p>长度分布同样关键。文本编码阶段的批大小可以很大，因为它的单请求计算量小、显存占用低；但 prompt 长度若呈长尾分布，长 prompt 会拉高该阶段的 P99，而短 prompt 又让大批失去意义。工程判断是：编码阶段按 token 数分桶，桶内大批、桶间独立排队，避免一个超长 prompt 拖住整批。去噪阶段则相反，批大小受 latent 尺寸与步数约束，高分辨率请求的批必须小，否则单批服务时间 $T_k^{\\mathrm{svc}}$ 线性上升，直接把端到端时延推到最慢阶段。</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</div>\n<p>这条式子给出负载配方的硬约束：端到端时延由最慢阶段决定，而每阶段吞吐 $\\lambda_k$ 与批大小 $B_k$ 成正比、与服务时间成反比。编码阶段可以把 $B_k$ 拉大而不显著抬高 $T_k^{\\mathrm{svc}}$，去噪阶段拉大批会同时抬高 $T_k^{\\mathrm{svc}}$，VAE 阶段则受 tile 并行度限制。三者不能共用同一个批大小，这正是“按阶段独立设定批”的由来。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-21\">二十一 · 并发与批大小的分段配方</h3>\n<p>并发量决定队列是否成为瓶颈。低并发时，各阶段队列深度 $Q_k$ 接近零，端到端时延约等于三段服务时间之和，拆分只增加固定开销；中高并发时，队列开始吸收阶段间的速率差，流水线才真正运转。配方上，编码阶段的并发承载能力最强，因为它可以靠大批把 $\\lambda_k$ 拉高；去噪阶段是全局瓶颈，其副本数应按 $\\text{Replicas}_{s}\\propto\\frac{\\lambda_{s}\\,\\bar{t}_{s}}{\\text{target util}}$ 配置，且 $\\lambda_s$ 要按分辨率池分别计算，高分辨率池的 $\\bar{t}_s$ 显著更长，需要更多副本或更激进的降分辨率策略；VAE 阶段按 tile 并行，其并发上限由显存能容纳的 tile 数与并行度共同决定。</p>\n<p>批大小的设定要跟着“服务时间对批的敏感度”走。编码阶段小 kernel 拖慢的本质是批太小导致 GPU 利用不足，因此它的批应尽量填满，直到 token 数触及显存或延迟上限；去噪阶段的批必须与分辨率池绑定，同一池内批大小一致才能让 $T_k^{\\mathrm{svc}}$ 可预测，跨池混批会让调度器失去对 P99 的估计；VAE 阶段的“批”其实是 tile 队列，批大小表现为同时在解码的 tile 数，受显存带宽约束而非算力约束。一个具体例子：同一网关下，低分辨率请求在去噪池 A 以较大批推进，高分辨率请求在池 B 以小批推进，两池共享同一 VAE 解码队列，VAE 按 tile 从队列取活，从而不被任一个去噪批绑架——这正是整机吞吐提升 1.5–2 倍的来源，而非某个阶段单独变快。</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>批的形态</th><th>批大小约束来源</th><th>并发扩展方式</th></tr></thead><tbody><tr><td>文本编码</td><td>token 桶内大批</td><td>显存与 P99 上限</td><td>数据并行副本</td></tr><tr><td>DiT 去噪</td><td>按分辨率/步数分池</td><td>latent 尺寸与步数决定的 $T_k^{\\mathrm{svc}}$</td><td>按池独立扩副本</td></tr><tr><td>VAE 解码</td><td>tile 队列</td><td>显存带宽与 tile 并行度</td><td>tile 并行 + 副本</td></tr></tbody></table>\n<p>代价面必须写清楚：分段批意味着三段各自持有显存缓冲，latent 队列本身要占显存与网络缓冲，跨节点时这部分开销随分辨率上升而放大。高分辨率 latent 的跨节点拷贝会直接侵蚀吞吐收益，因此负载配方里应把“高分辨率请求是否跨节点”作为一条显式规则，尽量让同一请求的三阶段落在同一节点或同一 NVLink 域内。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-22\">二十二 · 负载不对时的三种失效</h3>\n<p>第一种失效是“拆分无收益”。请求形态过于同质、并发过低时，三段串行本就没有相互等待，拆开后每段都要独立承担冷启动与显存碎片，队列空转，端到端时延反而因为两次 latent 拷贝而上升。判断信号是各阶段队列深度长期为零、P99 与单体部署持平甚至更差。此时应退回单体或只拆 VAE 一段。</p>\n<p>第二种失效是“瓶颈漂移未被跟踪”。负载配方假设去噪是瓶颈，但若 prompt 长度分布突然变长，编码阶段的小 kernel 拖慢会把它推成最慢阶段，$\\max_k$ 从去噪段跳到编码段，而副本弹性若只按去噪池配置，就会持续违约。调度器必须对三段都暴露队列深度与 P99，并按 $\\text{Replicas}_s$ 公式对每个阶段独立扩缩，而不是只盯去噪。滞后决策在负载突增时尤其致命：扩副本的冷启动时间若长于 SLO 窗口，扩出来的副本赶不上这一波请求，尾延迟已经违约。</p>\n<p>第三种失效是“无背压的队列积压”。上游编码阶段持续灌入 latent，下游去噪或 VAE 消费不及，$Q_k$ 单调上升，最终触发下游 OOM 或长尾请求无限堆积。背压的作用不是限流本身，而是把过载转成可预期的降级：按优先级丢弃低优先级请求，或对高分辨率请求降分辨率以缩短 $T_k^{\\mathrm{svc}}$，从而在不违反尾延迟的前提下保住达标率。缺少背压时，队列深度这个观测量失去意义，调度器看到的 P99 是积压后的假象，扩缩决策建立在错误信号上。</p>\n<ul><li>同质低并发：队列长期为空，拆分只增加拷贝开销。</li><li>瓶颈漂移：$\\max_k$ 换段而副本配置未跟随，持续违约。</li><li>无背压积压：$Q_k$ 失控导致 OOM 与长尾堆积，调度信号失真。</li></ul>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-23\">二十三 · 配方参数的工程取值逻辑</h3>\n<p>负载配方不是一组固定数字，而是一组随观测调整的规则。队列缓冲容量应设为“在目标 SLO 窗口内可吸收的请求量”，即缓冲上限与 $\\lambda_k\\cdot\\tau$ 同量级，超过这个量级的积压已无法在 $\\tau$ 内消化，继续缓冲只是推迟 OOM。副本弹性要有最小副本数与扩缩冷却期，避免负载抖动引发反复冷启动与显存碎片；冷却期的长度应由冷启动实测时间决定，而不是拍脑袋。</p>\n<p>降分辨率的触发点应绑定在队列深度而非单纯时延上：当某分辨率池的 $Q_k$ 超过其缓冲阈值，先降分辨率再考虑丢弃，因为降分辨率直接缩短 $T_k^{\\mathrm{svc}}$，是唯一能在不增加副本的前提下把 $\\lambda_k$ 拉回来的手段。优先级丢弃则用于保护尾延迟：低优先级请求在过载时被丢弃，使高优先级请求的 $Q_k$ 保持在阈值内，P99 达标率得以维持。这两条规则共同构成“过载时按优先级丢弃或降分辨率”的可执行版本。</p>\n<p>一个具体判断：若观测到 VAE 阶段队列深度持续高于去噪段、且 VAE 的 P99 随 tile 并行度饱和而不再下降，说明瓶颈已从去噪漂移到解码，此时应增加 VAE 副本或提高 tile 并行度，而不是继续给去噪池加副本——后者只会把更多 latent 灌进已经饱和的解码队列，加剧积压。这正是负载配方需要按阶段独立观测、独立扩缩的原因，也是调度器复杂度上升的代价所在。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-24\">二十四 · 适用边界的量化判断</h3>\n<p>拆分收益被通信开销侵蚀的程度，可以用“latent 传输时间占端到端时延的比例”来度量。跨节点时该比例随分辨率上升而上升，当它接近去噪段服务时间的量级时，拆分已不划算。规模上限受队列缓冲与调度器容量约束：阶段数越多、每阶段副本越多，调度器需要维护的队列与副本状态越多，决策延迟越长，在负载突增时越容易滞后。小规模单卡部署下，三段共享同一张卡的算力与显存，拆分带来的隔离收益被拷贝开销抵消，收益有限。</p>\n<p>因此负载配方的适用判断应落在三条线上：请求形态是否异质到需要分池、并发是否高到队列能吸收速率差、跨节点传输占比是否低于去噪服务时间。三条同时满足时，阶段级流水才把 1.5–2 倍的整机吞吐提升兑现；任一不满足，就应收缩拆分粒度，退回单体或只拆最异构的那一段。配方参数随负载漂移而调整，而不是一次设定后固化——这是本方法在工程上区别于静态部署配置的关键。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-25\">二十五 · 负载配方：混合分辨率、阶段独立批与背压边界</h3>\n<p>这套流水只有在请求形态是“混合分辨率文生图”时才划算：同一批请求里既有小尺寸快图、也有大尺寸多步图，分辨率与步数分布足够散，去噪阶段才能按分辨率与步数分池，把同池请求凑成大批做多步 DiT 前向。批大小按阶段独立设定——编码阶段大批吃满小 kernel，去噪阶段按池内分辨率定批，VAE 阶段按 tile 并行而非按请求批。端到端时延由最慢阶段决定：<div class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</div>若请求长度分布高度同质（全是同分辨率、同步数），分池失去意义，去噪阶段退化成单体批，拆分只剩队列开销。</p>\n<p>负载不对时的失效是结构性的。请求到达过于稀疏，编码阶段凑不满批，小 kernel 拖慢的问题反而被放大，而队列解耦带来的显存拷贝与跨节点网络开销照付；请求突增且缺乏背压，上游持续灌入会让下游解码队列积压直至 OOM 或长尾堆积，P99 直接违约。跨节点传输在高分辨率 latent 下开销更明显，可能吃掉 1.5–2 倍吞吐收益中的相当部分。多副本弹性扩缩还带来冷启动与显存碎片，调度器在突增时做出滞后决策，同样造成 SLO 违约。</p>\n<p>工程判断落在规模与配比上：小规模单卡部署拆分收益有限，阶段数越多、跨节点传输越多，收益被通信侵蚀，规模上限受队列缓冲与调度器容量约束。可用的配方是——编码用低算力卡配大批、去噪用高算力卡按池定批、解码用大显存卡按 tile 并行，量化按阶段选 FP8/NVFP4；同时把各阶段队列深度与 P99 时延暴露给调度器，过载时按优先级丢弃或降分辨率保尾延迟。它与连续批处理互补：前者解决阶段异构，后者解决请求到达异构，两者叠加才撑得住混合负载。</p>\n<h3 id=\"alg-stage-serving-pipeline-sec-26\">二十六 · 硬件档位：按阶段画像选卡，而不是按整机峰值</h3>\n<p>阶段级拆分的第一个部署决策是：三张卡还是三档卡。文本编码阶段的负载是短序列 transformer 前向，算力需求低、显存需求中等、kernel 粒度小，瓶颈在发射与调度而非张量核吞吐；去噪阶段的 DiT 多步前向是整条管线的主算力消耗，吃满 tensor core、对显存带宽与容量都敏感；VAE 解码阶段是卷积与上采样为主的分块并行负载，算力利用率中等但激活显存随分辨率平方增长。把这三者塞进同一档 GPU，等价于用去噪阶段的卡去跑编码阶段的小 kernel，SM 占用率长期低位，这正是单体部署空转的来源。</p>\n<p>因此硬件档位的配方原则是“按阶段画像配比，而非按整机峰值配比”。编码阶段用低算力、高主频、显存够放 prompt batch 与 KV 的卡即可，重点是把 batch 拉大以摊薄 kernel 发射开销；去噪阶段用满配算力卡，且优先保证单卡显存能容纳目标分辨率下的 DiT 权重加激活加 KV 式中间张量；解码阶段用大显存卡，因为 VAE 分块解码的 tile 缓冲与输出像素缓冲是显存密集型而非算力密集型。异构档位带来的直接代价是运维面变宽：三档卡的驱动、拓扑、量化支持度不一致，镜像与算子库要按档位分别验证。收益则体现在配比上——用去噪卡的单价去覆盖编码阶段的低利用率，是纯粹的浪费。</p>\n<p>一个具体判断：若服务以中低分辨率为主、去噪步数少，则去噪阶段相对编码与解码的算力占比下降，异构档位的收益变小，此时更应关注阶段间传输而非档位差异；反之高分辨率、多步数负载下，去噪阶段独占算力大头，异构配比的性价比最高。档位选择要和负载配方绑定评估，不能脱离请求形态单独定。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-27\">二十七 · 并行拓扑：阶段内数据并行，阶段间流水</h3>\n<p>拓扑上只做两件事：阶段内做数据并行，阶段间做流水解耦。阶段内不做张量并行，原因是三阶段的单批服务时间 $T_k^{\\mathrm{svc}}$ 差异极大，张量并行会把通信开销引入本来就不重的编码与解码阶段，得不偿失；去噪阶段若单卡显存放不下目标分辨率，才在该阶段内部引入张量并行或序列并行，且只在这一阶段引入。阶段间不做同步调用，而是用 latent 队列解耦，让上游阶段的输出速率与下游阶段的消费速率彼此独立。</p>\n<p>流水拓扑的容量约束由前文给出的公式刻画：</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</div>\n<p>这个式子说明端到端时延由最慢阶段决定，而某阶段的吞吐 $\\lambda_k$ 由该阶段批大小 $B_k$ 与单批服务时间 $T_k^{\\mathrm{svc}}$ 共同决定。拓扑设计的直接推论是：不要试图让三阶段的副本数按 1:1:1 配平，而应按 $\\lambda_k$ 反推副本数，让各阶段的稳态吞吐对齐到同一目标请求速率。副本配比失衡时，慢阶段的队列 $Q_k$ 单调增长，端到端时延被这一项拖垮，而不是被任何单阶段的 $T_k^{\\mathrm{svc}}$ 拖垮。</p>\n<p>跨节点是拓扑的代价分界线。同节点内 latent 队列走显存到显存的拷贝，开销可接受；跨节点则要走网络，高分辨率 latent 的体积随分辨率与通道数上升，拷贝与传输开销会侵蚀拆分收益。工程判断是：优先把相邻阶段放在同一节点或同一 NVLink 域内，把跨节点边界放在 latent 体积最小的地方——编码到去噪的边界 latent 尚未经过多步演化，去噪到解码的边界 latent 已是最终潜变量，两者体积相当，因此更现实的做法是把去噪与解码放在同一高带宽域，把编码阶段外置。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-28\">二十八 · 量化方案：按阶段的数值敏感度分档</h3>\n<p>量化不能整条管线一刀切。三阶段对数值误差的敏感度不同：文本编码阶段的输出是条件嵌入，误差会被后续多步去噪反复放大，宜保守；去噪阶段的 DiT 主干是算力与带宽的主战场，量化收益最大，但需按层分档，注意力与残差路径保留更高精度；VAE 解码阶段直接决定像素输出，量化误差表现为可见的色偏与纹理劣化，且解码是显存密集型而非算力密集型，量化的吞吐收益有限而质量风险高，宜保持高精度或用较轻的量化。</p>\n<p>配方上按阶段给出量化档位表，而不是给出单一精度：</p>\n<table class=\"mini\"><thead><tr><th>阶段</th><th>量化取向</th><th>主要收益</th><th>主要风险</th></tr></thead><tbody><tr><td>文本编码</td><td>FP8 权重、激活保守</td><td>降低权重带宽占用</td><td>条件嵌入误差被多步放大</td></tr><tr><td>DiT 去噪</td><td>NVFP4/FP8 分块混合</td><td>算力与显存带宽双收益</td><td>需分块校准，层间敏感度不均</td></tr><tr><td>VAE 解码</td><td>FP8 或保持高精度</td><td>有限</td><td>像素级可见劣化</td></tr></tbody></table>\n<p>这里的工程代价要算清楚：去噪阶段量化的收益是显存占用与带宽下降，直接抬高该阶段可承载的批大小 $B_k$，从而抬高 $\\lambda_k$；而编码与解码阶段量化的收益主要体现在权重驻留显存上，对 $T_k^{\\mathrm{svc}}$ 的改善有限。因此量化预算应集中投在去噪阶段，且必须与分块校准流程绑定——校准数据要覆盖目标分辨率与步数分布，否则分块量化在长尾分辨率上的误差会以可见形式暴露。量化方案与硬件档位联动：低算力编码卡若支持 FP8 则用之降带宽，不支持则不必强上。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-29\">二十九 · KV 与中间态策略：latent 队列的缓冲与生命周期</h3>\n<p>扩散管线里没有自回归解码那种逐 token 增长的 KV cache，但有等价物：条件嵌入、latent 中间态、以及去噪阶段每步复用的时间步嵌入与缓存特征。阶段级拆分把这些中间态从“进程内变量”变成“跨阶段消息”，其生命周期管理直接决定显存碎片与队列稳定性。latent 队列必须有显式容量上限，容量按“下游阶段一个批次的消费量 × 安全系数”设定，而不是无限缓冲——无限缓冲会把背压问题转化为 OOM 问题。</p>\n<p>缓冲策略的核心是队列深度 $Q_k$ 与背压阈值的联动。上游阶段写队列前检查下游队列深度，超过阈值则阻塞或降速，这是防止雪崩的唯一手段；下游阶段消费后释放缓冲，释放时机要早于该批次的完整后处理，否则缓冲占用被后处理拖长。显存碎片来自两处：不同分辨率的 latent 体积不同，固定大小的缓冲池会产生内部碎片；副本弹性扩缩时新副本申请大块显存，与既有副本的碎片化分配冲突。对策是按分辨率分池管理缓冲，池内用统一尺寸块，池间独立伸缩。</p>\n<p>代价量化：latent 队列的显存占用是常驻成本，按“队列容量 × 单条 latent 体积 × 阶段数”估算，高分辨率下这一项不可忽略，会挤压去噪阶段可用于批大小的显存，反过来压低 $\\lambda_{\\text{denoise}}$。因此队列容量不是越大越稳，而是要在“吸收突发”与“让出去噪显存”之间取平衡。一个可操作的判断：把队列容量设为下游阶段单批消费量的两到三倍，超出部分用背压而非缓冲吸收。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-30\">三十 · 调度参数：副本弹性、优先级与降级路径</h3>\n<p>调度参数分三层：副本弹性、请求优先级、过载降级。副本弹性按前文公式的副本配比思路执行，各阶段独立扩缩，扩缩信号取该阶段的队列深度与 P99 服务时间，而非整机利用率——整机利用率会被最忙阶段主导，掩盖空闲阶段的真实需求。弹性带来的代价是冷启动：新副本要加载权重、初始化算子库、预热显存池，这段时间内该阶段吞吐为零，若扩缩决策滞后于负载突增，就会出现“扩容未完成、队列已积压”的窗口，直接表现为 SLO 违约。对策是保留最小热备副本数，并对扩容设置提前量触发阈值。</p>\n<p>优先级与降级是过载时的最后一道闸。请求按优先级分层，高优先级请求在队列满时插队；降级路径按“降分辨率 → 降步数 → 丢弃低优先级”的顺序执行，因为降分辨率同时降低去噪与解码两阶段的单请求成本，是最有效的降级手段。降级必须由网关或调度器统一决策，而不是各阶段自行其是，否则会出现上游按高分辨率灌入、下游按低分辨率消费的错配。</p>\n<p>调度参数的联动关系要写进配置而非散落在代码里：副本数、队列容量、背压阈值、降级触发线四者共同决定稳态行为。一个可复现的配置思路是——先固定负载配方（混合分辨率、目标 P99 与达标率），再按 $\\lambda_k$ 反推各阶段副本配比，再按单批消费量定队列容量，最后用压测把背压阈值与降级触发线校准到“队列深度接近容量但未溢出”的位置。这套顺序不能颠倒，因为副本配比决定了稳态吞吐，队列容量决定了突发吸收能力，背压与降级只在前两者定好之后才有意义。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-31\">三十一 · 可复现配置的落地顺序与验收口径</h3>\n<p>把上述五节收束成一条可复现的落地路径，顺序是：定负载配方 → 定硬件档位与拓扑 → 定量化档位 → 定缓冲与队列 → 定调度参数 → 压测校准。每一步的产出是一份显式配置，而不是调参经验。硬件档位与拓扑决定跨节点边界位置，量化档位决定各阶段的显存与带宽预算，缓冲与队列决定常驻显存占用，调度参数决定过载行为。任何一步的改动都会传导到下游，因此配置要版本化并记录改动链路。</p>\n<p>验收口径要盯住阶段级指标而非整机指标：各阶段的队列深度分布、P99 服务时间、副本利用率、跨节点 latent 传输开销占比、降级触发次数。整机吞吐提升 1.5–2 倍是拆分收益的锚点，但验收不能只看吞吐——若 P99 达标率未达目标，或降级触发频繁，则说明副本配比或队列容量失配，应回到副本反推那一步重算，而不是靠加大缓冲掩盖。失败模式要提前写进验收清单：跨节点 latent 传输开销吃掉吞吐收益、弹性扩缩滞后导致 SLO 违约、队列无背压导致下游 OOM。这三条各自对应一个配置项，验收时逐条核对。</p>\n<p>最后落到一个具体机制上：调度器的扩缩决策应以“下游队列深度增速”而非“当前深度”作为触发量，因为深度是滞后指标，增速是超前指标；当某阶段队列深度在短时间内持续上升，即使尚未触及阈值，也应提前扩容，把冷启动窗口压在队列溢出之前。这一条把副本弹性从被动响应变成主动预判，是阶段级流水在负载突增下保持 SLO 的关键工程判断。</p>\n<h3 id=\"alg-stage-serving-pipeline-sec-32\">三十二 · 端到端时延由最慢阶段钉住：把 max 拆成可观测的量</h3>\n<p>阶段级流水一旦拆开，端到端时延就不再是「一条 GPU 上顺序跑完三段」的简单加和，而是三个异步队列串联后的稳态排队结果。前文给出的核心式子是 <span class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</span> 它的工程含义比数学含义更重要：端到端时延由最慢阶段决定，而「最慢」是随负载漂移的。文本编码阶段单批服务时间短、批可以开得很大，$\\lambda_{\\text{enc}}$ 很容易做高；VAE 解码阶段单批服务时间长、tile 并行度受显存带宽约束，$\\lambda_{\\text{dec}}$ 往往成为瓶颈；去噪阶段则随分辨率与步数分池，$\\lambda_{\\text{den}}$ 在不同池之间差异巨大。因此运维上必须把每个阶段的 $Q_k$、$\\lambda_k$、$T_k^{\\mathrm{svc}}$ 分别暴露成指标，而不是只报一个端到端 P99——否则尾延迟劣化时无法判断是哪个阶段在积压。</p>\n<p>具体机制上，网关在请求进入时打上分辨率与步数标签，去噪池按标签路由，解码队列按 tile 数估算服务时间并做准入。一个可操作的伪代码思路是：调度器每轮采样各阶段队列深度与近期 $\\lambda_k$，计算 $\\hat{T}_{\\mathrm{e2e}}=\\max_k(Q_k/\\lambda_k+T_k^{\\mathrm{svc}})$，若 $\\hat{T}_{\\mathrm{e2e}}$ 逼近 $\\tau$ 则对上游阶段施加背压（降低准入速率）而非直接扩副本——因为扩副本有冷启动，而背压是毫秒级的。代价方面：这套观测本身要占用调度器 CPU 与少量显存做队列元数据，跨节点时队列深度采样还会引入网络往返；收益是把尾延迟从「不可解释的抖动」变成「可归因的积压」。例子：混合分辨率负载下，高分辨率请求把去噪池的 $T_k^{\\mathrm{svc}}$ 拉长，若不做分池，低分辨率请求会被同一队列拖到长尾，分池后低分辨率池的 P99 与高分辨率池解耦。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-33\">三十三 · 显存：三阶段峰值不同步，副本弹性撞上碎片</h3>\n<p>单体部署时显存峰值出现在去噪阶段（激活、KV 类中间张量、多步迭代的常驻缓冲），VAE 阶段反而空转；拆成三阶段后，每个副本的显存画像被单独定义：编码副本只需容纳 prompt 批与文本侧中间量，去噪副本要按最大分辨率池预留激活与权重，解码副本要按 tile 数与输出分辨率预留像素缓冲。问题在于多副本弹性：扩缩容时新副本要加载权重、初始化 CUDA context、预分配队列缓冲，这段冷启动期间显存是被占住但不产出吞吐的。更隐蔽的是显存碎片——不同分辨率池的激活尺寸不同，反复扩缩会让分配器留下无法复用的大块空洞，表现为「显存够但分配失败」。</p>\n<p>工程判断是：解码副本按「大显存卡」选型，因为 VAE tile 并行对显存容量的需求是刚性的、对算力反而不敏感；去噪副本按分辨率池做静态分区而非动态共享，牺牲一点利用率换掉碎片风险；编码副本用小卡、允许更高的副本数以便快速弹性。代价量化上，队列缓冲本身要占显存：latent 队列深度 × 单条 latent 尺寸 × 副本数，高分辨率 latent 下这个量不可忽略，且跨节点时同一份 latent 在发送缓冲与接收缓冲各存一份，等于显存拷贝翻倍。例子：当一个高分辨率池突然扩容，新副本预分配的大块激活会挤占同卡上低分辨率池的缓存空间，若不做池间隔离，低分辨率池的 P99 会先崩——这是规模上去后最先暴露的显存侧故障。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-34\">三十四 · 带宽与通信：latent 过网是收益的隐形税</h3>\n<p>阶段间解耦靠 latent 队列，队列跨节点时 latent 必须序列化过网。这条路径的成本由三部分构成：显存到显存的拷贝（同节点内）、序列化/反序列化、以及网络传输本身。高分辨率 latent 的张量尺寸随分辨率平方增长，而 NVLink 5 域内带宽虽高，跨节点走的是另一套 fabric，有效带宽与延迟都差一个档。于是出现一个临界点：当阶段间传输时间占到 $T_k^{\\mathrm{svc}}$ 的可观比例时，拆分带来的并行收益被通信开销侵蚀，这与前文「阶段数越多、跨节点传输越多，收益被侵蚀」的边界判断一致。</p>\n<p>可操作的机制是「亲和性调度」：把同一请求链路上相邻阶段的副本尽量放在同一 NVLink 域内，让 latent 走域内高带宽路径；跨域只在弹性扩容或负载倾斜时才发生。另一个机制是 latent 压缩——在队列里传低精度 latent 而非全精度，代价是数值精度损失需要与去噪阶段的量化策略联合评估（这部分与 DiT 量化条目共享边界，此处只指路）。公式上可以把传输代价并入服务时间：<span class=\"formula\">$$T_k^{\\mathrm{svc}}=T_k^{\\mathrm{comp}}+\\frac{S_{\\mathrm{latent}}}{BW_{\\mathrm{eff}}}$$</span> 其中 $S_{\\mathrm{latent}}$ 是单条 latent 字节数，$BW_{\\mathrm{eff}}$ 是含协议开销的有效带宽。代价例子：解码副本扩容到另一台机器后，去噪到解码的 latent 全部过网，若 $S_{\\mathrm{latent}}$ 大而 $BW_{\\mathrm{eff}}$ 有限，解码阶段的等效 $T_k^{\\mathrm{svc}}$ 被拉长，$\\lambda_{\\text{dec}}$ 下降，端到端 max 直接抬升——吞吐收益在跨节点比例上升时被吃掉。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-35\">三十五 · 功耗与利用率：空转被拆掉，但新空转在队列边界出现</h3>\n<p>单体部署的功耗病灶是阶段间不同步：VAE 阶段 GPU 空转但时钟不降，文本编码阶段小 kernel 打不满 SM 却在耗电。拆分后每个副本的负载更均匀，SM 占用率提升，单位 token 或单位图像的能耗下降——这是 1.5–2 倍整机吞吐背后的能效逻辑。但拆分也制造了新的空转点：队列为空时副本在等上游，队列满时上游在等下游，这两种等待都不产出但占着功耗。工程上要把「等队列」与「算不动」区分开：前者应触发降频或副本回收，后者才需要扩容。</p>\n<p>机制上，调度器可以按队列深度做功耗感知的副本管理：深度持续低于阈值一段时间则缩副本，深度持续高于阈值则扩，中间区间维持。代价是缩副本同样有冷启动，频繁抖动会让有效吞吐低于稳态。例子：夜间低峰时编码副本大量空转，若不做回收，整机功耗被闲置副本拖住；但若回收过激，早高峰第一波请求撞上冷启动，P99 直接违约。这里的工程判断是给缩容设滞回区间与最小驻留时间，把功耗收益让位于尾延迟稳定性。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-36\">三十六 · 尾延迟与规模上限：先崩的是队列缓冲与调度器，不是 GPU</h3>\n<p>规模上去以后，最先崩的往往不是算力，而是两个软资源：队列缓冲容量与调度器决策速度。队列缓冲是显存与网络的联合预算，深度设小了背压频繁触发、吞吐上不去；设大了积压时延不可控、OOM 风险上升。调度器决策速度则受限于采样周期与扩缩冷启动：负载突增时，调度器看到的是上一周期的队列深度，做出的扩容决策落地时负载形态已变，滞后决策直接导致 SLO 违约——这正是前文列出的失败模式之一。</p>\n<p>可操作的机制是分层背压：网关层按优先级丢弃或降分辨率（过载时保尾延迟），阶段层按队列深度做准入控制，副本层按滞回区间扩缩。公式上，副本数与负载的关系是 <span class=\"formula\">$$\\text{Replicas}_{s}\\propto\\frac{\\lambda_{s}\\,\\bar{t}_{s}}{\\text{target util}}$$</span> 它说明副本需求正比于到达率与服务时间、反比于目标利用率；目标利用率定得越高，副本越少但尾延迟越脆。工程判断是把 target util 按阶段差异化：编码阶段可以定高（服务时间短、抖动小），解码阶段必须定低（服务时间长、方差大），去噪阶段按池分别定。例子：一个去噪池在分辨率突增时 $\\bar{t}_s$ 翻倍，若 target util 不变，所需副本数翻倍，而扩容冷启动期间队列积压，尾延迟先崩——此时正确的动作是降分辨率而非硬扩，因为降分辨率同时降低了 $\\bar{t}_s$ 与 $S_{\\mathrm{latent}}$，一箭双雕。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-37\">三十七 · 规模化的工程判断：收益曲线在跨节点比例上升时掉头</h3>\n<p>把上述代价合起来看，阶段级流水的净收益是一个关于「跨节点传输占比」的递减函数。小规模单卡部署下，三阶段同卡、latent 走显存拷贝，拆分收益有限甚至为负（多副本调度开销大于并行收益）；中等规模同 NVLink 域内，latent 传输便宜，1.5–2 倍吞吐可以拿到；大规模跨节点时，latent 过网与冷启动碎片同时上升，收益被侵蚀。因此扩容决策不应只看 GPU 数量，而要看「同一请求链路跨节点跳数」这个指标——它是阶段级流水规模上限的直接度量。</p>\n<p>具体机制上，可以用链路亲和性打分做放置：请求的编码、去噪、解码副本尽量落在同一 NVLink 域，域内副本数不足时才跨域，并把跨域跳数作为调度器的约束项而非事后观测。代价是放置自由度下降、局部热点更难疏散，但换来的是 $T_k^{\\mathrm{svc}}$ 中传输项可控。最后落在工程判断上：当跨域跳数均值超过阈值时，应停止横向扩副本、转向纵向提分辨率池的批效率，或者退回单体部署加连续批处理——因为此时阶段拆分的边际收益已经低于它带来的队列与调度复杂度。这个阈值不是拍脑袋，而是用 $\\hat{T}_{\\mathrm{e2e}}$ 中传输项占比与 P99 达标率的联合观测来定的。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-38\">三十八 · 规模上去以后：先崩在跨节点 latent 搬运，再崩在调度器</h3>\n<p>阶段拆分的收益来自各阶段独立 batch，但代价随规模非线性放大。端到端时延由最慢阶段决定：<div class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</div>单机三阶段同卡时，latent 队列只是显存里的指针传递；一旦去噪池与 VAE 池跨节点，每张 latent 都要走一次显存拷贝加一次网络传输。高分辨率 latent 的字节数随 H×W 增长，而 VAE 解码本身是带宽密集的 tile 并行，跨节点搬运正好压在这条最敏感的路径上——吞吐收益被通信开销侵蚀，是这套方案最先失效的地方。判断阈值很直接：把单张 latent 的传输时间与 VAE 单 tile 服务时间相比，前者接近后者量级时，拆分就不再划算。</p>\n<p>第二个崩点是副本弹性。Replicas 按 <span class=\"formula\">$$\\text{Replicas}_{s}\\propto\\frac{\\lambda_{s}\\,\\bar{t}_{s}}{\\text{target util}}$$</span> 配置，但去噪阶段的冷启动要重新加载权重、重建 CUDA Graph 与 TMEM 布局，VAE 阶段的大显存卡还会因反复扩缩留下显存碎片。负载突增时调度器依据的是滞后的队列深度与 P99 采样，扩出来的副本赶不上第一波尖峰，SLO 违约发生在扩容完成之前。因此弹性策略必须与背压绑定：队列深度超阈值先降分辨率或按优先级丢弃，再触发扩容，而不是让上游继续灌入直到下游 OOM。</p>\n<p>第三是功耗与异构档位的错配。编码阶段用低算力卡、去噪用高算力卡、解码用大显存卡，看似省，但三档硬件的空转功耗与跨档通信让整机功耗曲线变得难预测；去噪池按分辨率与步数分池后，各池的 util 目标不同，全局功耗峰值往往出现在多个池同时满批的时刻。规模上限因此不在单卡算力，而在队列缓冲容量与调度器可管理的副本数：阶段数越多、跨节点边越多，调度器状态空间越大，决策延迟越长，尾延迟越难压住。小规模单卡部署下拆分收益有限，这套流水要到多卡多节点、且阶段资源需求明显分化时才值得付通信与调度的账。</p>\n<h3 id=\"alg-stage-serving-pipeline-sec-39\">三十九 · 精度漂移：三阶段各自失守的位置</h3>\n<p>阶段级流水把一条扩散管线切成三段独立部署，精度问题也随之被切成三份互不相同的故障面，任何一份失守都会在最终图像上以不同形态暴露。文本编码阶段的风险集中在激活值范围：prompt 长度分布长尾、大批量拼接后 padding 位置与真实 token 的激活尺度差异被 FP8 的 per-tensor 缩放抹平，表现为语义漂移——同一 prompt 在不同批大小下生成结果不一致。去噪阶段的风险在累积误差：多步 DiT 前向中每一步的量化噪声都会进入下一步的输入，NVFP4 的块级缩放若校准集未覆盖当前分辨率池，误差沿步数放大，表现为纹理崩坏或颜色偏移。VAE 解码阶段的风险在 tile 边界：分块并行解码时相邻 tile 的量化与归一化若不一致，接缝处出现亮度台阶。</p>\n<p>诊断的关键是把“最终图像不对”还原到“哪一段的哪一批”。做法是在每个阶段的出口埋数值探针：编码阶段记录 latent 的均值、方差与最大绝对值；去噪阶段按步记录 latent 的 L2 范数增量；解码阶段记录 tile 接缝两侧的像素差。三者与基线（同 prompt、同 seed、FP16 参考路径）比对，偏差超阈值即定位到阶段。代价是探针本身要读回显存，全量记录会打断流水，因此只在采样批次上开启，采样率与队列深度联动——队列积压时降采样率，避免诊断本身成为瓶颈。</p>\n<p>回滚策略按阶段粒度而非整机粒度：编码阶段精度异常时切回 FP16 编码副本（该阶段算力需求低，回滚的吞吐代价小）；去噪阶段异常时把对应分辨率池的量化档位降一级（NVFP4→FP8），只影响该池的在途请求；解码阶段接缝问题则回滚 tile 重叠策略而非精度。举例：混合分辨率负载下，高分辨率池的 latent 动态范围显著大于低分辨率池，若两池共用一份 NVFP4 校准参数，高分辨率池先崩——此时按池隔离校准并只回滚该池，避免拖累低分辨率池的吞吐。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-40\">四十 · OOM 的三条路径与队列背压</h3>\n<p>阶段拆分后 OOM 不再是一个整机问题，而是三条独立路径。第一条是解码队列积压：去噪阶段吞吐高于解码阶段时，完成去噪的 latent 在解码队列中堆积，每个 latent 占用的显存与其分辨率成正比，高分辨率 latent 尤其昂贵，队列缓冲耗尽即 OOM。第二条是弹性扩容的显存碎片：新副本冷启动时加载权重与分配 KV/latent 缓冲，与既有副本的显存池竞争，碎片化使可用大块显存不足。第三条是批抖动引发的瞬时峰值：去噪阶段按分辨率分池，某池突发大批请求时批大小上调，激活显存瞬时抬升越过水位线。</p>\n<p>端到端时延由最慢阶段决定，这一关系直接给出背压的设计依据：</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</div>\n<p>其中 $Q_k$ 为第 $k$ 阶段队列深度，$\\lambda_k$ 为该阶段吞吐，$B_k$ 为批大小，$T_k^{\\mathrm{svc}}$ 为单批服务时间。当某阶段 $\\lambda_k$ 下降（例如解码阶段 tile 并行度受显存限制），$Q_k/\\lambda_k$ 线性上升，若不施加背压，上游持续灌入只会把队列推向 OOM 而非提升吞吐。工程做法是给每个队列设高水位与低水位：高水位触发上游降速（编码阶段减小批、去噪阶段暂停取 latent），低水位恢复；同时对队列中请求按优先级排序，过载时优先丢弃低优先级或降分辨率重排，保证尾延迟。代价是背压期间上游 GPU 利用率下降，整机吞吐让位于 SLO——这正是阶段级流水用吞吐换尾延迟可控的交换点。</p>\n<p>具体例子：解码阶段因 tile 并行度受限，$\\lambda_{\\text{dec}}$ 低于 $\\lambda_{\\text{den}}$，latent 队列持续增长。若不做背压，队列缓冲填满后新 latent 无处写入，解码副本 OOM 重启，冷启动期间所有在途请求超时。加背压后，去噪阶段在高水位暂停取队列，编码阶段同步降批，队列稳定在高水位以下，P99 尾延迟被压在阈值内，代价是去噪 GPU 短时空转。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-41\">四十一 · 批抖动与路由不均的耦合诊断</h3>\n<p>批抖动在阶段级流水中有两个来源：请求到达的泊松波动，以及分池策略导致的池间不均衡。去噪阶段按分辨率与步数分池，池内批大小独立设定，若路由把高分辨率请求集中到某一副本而低分辨率副本空闲，则出现“整体利用率健康、单池排队严重”的假象。诊断不能只看整机 GPU 利用率，必须看每池的队列深度、批大小时间序列与副本间负载方差。负载方差持续偏高即路由不均的信号。</p>\n<p>路由不均的根因通常在网关的哈希策略：按 prompt 哈希做亲和路由会把相似长度的请求打到同一副本，而相似长度往往对应相似分辨率需求，于是副本间负载分化。修正方式是改为按池容量加权的轮询或最少队列优先，并把副本的实时队列深度反馈给网关。代价是网关需要维护副本状态，跨节点时状态同步引入额外延迟，因此反馈周期要与队列深度变化的时间尺度匹配——反馈过慢则路由滞后，过快则网关成为热点。</p>\n<p>批抖动的另一个表现是批大小在高低之间振荡：背压降批后队列排空，背压解除又立即升批，队列再次积压。这是控制环缺少阻尼的典型症状。工程上给批大小加变化率限制与滞回区间，使批大小在低水位与高水位之间平滑过渡，代价是稳态吞吐略低于理论最优，但消除了振荡带来的 P99 尖刺。举例：某池批大小在 8 与 32 之间反复跳变，P99 时延随之出现周期性尖刺；加滞回后批大小稳定在 16–24 区间，尖刺消失，平均吞吐仅小幅下降。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-42\">四十二 · 尾延迟尖刺的四个来源</h3>\n<p>P99 尾延迟是阶段级流水最敏感的指标，尖刺来源可归为四类，诊断时按“是否与队列深度同步”区分。第一类是冷启动：弹性扩容的新副本加载权重、预热 kernel、填充显存池，期间不接流量或接流量但服务时间远高于稳态，尖刺与扩容事件同步。第二类是跨节点 latent 传输：阶段部署在不同节点时，latent 队列的显存拷贝与网络传输进入关键路径，高分辨率 latent 下传输时间占比上升，尖刺与网络拥塞同步。第三类是调度滞后：负载突增时调度器决策慢于队列增长，副本扩容完成时积压已形成长尾，尖刺滞后于负载突增。第四类是 GC 式停顿：显存池的碎片整理或队列缓冲的重分配造成短暂停顿，尖刺周期性与分配事件同步。</p>\n<p>诊断手段是把 P99 分解到阶段：每阶段暴露自己的 P99 服务时间与排队时间，端到端 P99 的增量归因到贡献最大的阶段。若尖刺出现在排队时间而非服务时间，指向调度与背压；若出现在服务时间，指向冷启动、传输或停顿。监控上还需记录扩容事件、跨节点传输时延、显存分配失败次数，三者与尖刺的时间对齐即可定位根因。</p>\n<p>回滚与缓解按来源分治：冷启动尖刺用副本预热池缓解（常驻少量热副本，扩容时从热副本克隆状态），代价是常驻副本占用显存、降低峰值利用率；传输尖刺用 latent 压缩或阶段亲和部署（把解码阶段与去噪阶段放在同节点）缓解，代价是牺牲硬件档位异构的灵活性；调度滞后用预测式扩容（按队列增长速率提前扩容）缓解，代价是过度扩容带来的显存碎片；停顿尖刺用预分配缓冲池缓解，代价是稳态显存占用上升。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-43\">四十三 · 监控面与回滚的工程判断</h3>\n<p>阶段级流水的监控面必须覆盖三层的交叉：阶段层（队列深度、批大小、P99 服务与排队时间、精度探针偏差）、副本层（显存水位、碎片率、冷启动次数、扩容事件）、链路层（跨节点 latent 传输时延与丢包、网关路由分布）。三层缺一层就无法完成归因——只有阶段层能看到尖刺，只有副本层能看到碎片，只有链路层能看到传输。监控采样率与队列深度联动，避免监控本身消耗显存带宽。</p>\n<p>回滚的粒度判断是这套系统的核心工程决策。整机回滚（全部阶段切回上一稳定配置）最安全但代价最大，吞吐损失覆盖全管线；阶段回滚只影响单段，但要求阶段间接口（latent 格式、队列协议）保持兼容；池级回滚最细，只影响单分辨率池，但要求校准与配置按池隔离。判断依据是故障是否跨池、是否跨阶段：精度问题通常池级可隔离，OOM 与调度问题往往阶段级，接口协议变更引发的故障才需要整机回滚。</p>\n<p>回滚触发条件要写成可执行的判据而非人工判断：某阶段 P99 超过阈值持续若干采样窗口、精度探针偏差超阈值、副本 OOM 重启次数超阈值，任一满足即自动回滚到该阶段的上一配置版本，并冻结该阶段的弹性扩容直到人工确认。代价是自动回滚可能误触发（例如负载突增被误判为故障），因此阈值需与负载配方绑定，按池设定而非全局统一。举例：高分辨率池的 P99 天然高于低分辨率池，若用全局阈值，高分辨率池会频繁误触发回滚；按池设阈值后误触发消除，同时保留了对真实故障的响应。</p>\n<p>最后一个判断落在容量与弹性的关系上：副本数按阶段独立配置，$\\text{Replicas}_{s}\\propto \\lambda_{s}\\bar{t}_{s}/\\text{target util}$，其中 $\\lambda_s$ 为该阶段到达率、$\\bar{t}_s$ 为平均服务时间。当某阶段的 target util 设得过高，该阶段在负载波动下频繁触顶，尾延迟尖刺与扩容事件耦合；设得过低则常驻副本过多，显存碎片与冷启动风险上升。工程上把 target util 与池的 P99 预算绑定，让每个池的副本数由该池的尾延迟预算反推，而不是由整机利用率反推——这是阶段级流水在稳定性上的最终落点。</p>\n\n\n<h3 id=\"alg-stage-serving-pipeline-sec-44\">四十四 · 阶段拆分的失效边界与回滚判据</h3>\n<p>三阶段拆分的收益在跨节点时最先被侵蚀：latent 在编码→去噪、去噪→解码之间要落显存缓冲并走网络，高分辨率 latent 的字节数随 H×W 线性放大，拷贝与传输开销直接叠加到 <span class=\"inline-math\">T<sub>e2e</sub></span> 的 <span class=\"inline-math\">max<sub>k</sub></span> 项上。诊断上不能只看整机吞吐，要在每阶段埋两个计数器：队列深度 <span class=\"inline-math\">Q<sub>k</sub></span> 的滑动均值与 P99 服务时间 <span class=\"inline-math\">T<sub>k</sub><sup>svc</sup></span>。当某阶段 <span class=\"inline-math\">Q<sub>k</sub></span> 持续单调上升而 <span class=\"inline-math\">T<sub>k</sub><sup>svc</sup></span> 平稳，说明瓶颈在下游而非本阶段算力，此时扩容本阶段副本只会加剧 latent 堆积与显存碎片。</p>\n<div class=\"formula\">$$\\text{backpressure}_{k}=\\mathbb{1}\\left[\\frac{Q_k}{\\lambda_k}&gt;\\alpha\\cdot\\tau\\right],\\quad \\text{rollback}=\\mathbb{1}\\left[\\text{P99}_{e2e}&gt;\\tau \\ \\wedge\\ \\text{throughput}_{\\text{split}}&lt;\\text{throughput}_{\\text{mono}}\\right]$$</div>\n<p>回滚判据要写成可执行的布尔条件而非人工判断：当阶段化部署的 P99 超过 SLO 阈值 τ，且整机吞吐已低于单体部署基线（拆分收益被通信与调度开销吃掉），就应把管线合回单体或退化为两阶段（编码+去噪合并、解码独立）。精度问题则单独走一条线：按阶段选 FP8/NVFP4 后，若解码阶段出现 tile 边界接缝或色彩漂移，优先怀疑 VAE 解码的量化误差累积而非去噪步数，因为解码是逐 tile 并行的，误差不跨步传播但会跨 tile 拼接放大。监控上给每阶段加一条 latent 校验和（低精度哈希）比对，能在不落盘全量 latent 的前提下定位是传输损坏还是量化失真。</p>\n<p>批抖动与路由不均的代价体现在副本利用率方差上：<span class=\"inline-math\">Replicas<sub>s</sub> ∝ λ<sub>s</sub> t̄<sub>s</sub> / target util</span>，若网关按请求数而非按分辨率/步数加权路由，去噪池里高分辨率请求会集中打到少数副本，造成该副本 <span class=\"inline-math\">T<sup>svc</sup></span> 抬升、队列尖刺，而低分辨率副本空转。工程判断是：路由键必须包含分辨率桶与步数桶，扩缩决策用队列深度的一阶差分而非绝对值，避免负载突增时的滞后扩容；冷启动副本在预热完成前不接入队列，防止显存碎片与首请求超时叠加成尾延迟尖刺。</p>\n<h3 id=\"alg-stage-serving-pipeline-sec-45\">四十五 · 对照轴：切分维度与耦合点</h3>\n<p>把本方法放进同族算法的坐标系，第一根轴不是“快不快”，而是“沿哪个维度切”。单体部署不切；patch 级调度沿空间切（把一张图拆成块，块级跳步、块级缓存）；连续批处理沿时间切（请求到达时刻不同，用迭代级调度填满 batch）；本方法沿管线阶段切（文本编码、DiT 去噪、VAE 解码各自成服务）。三种切法解决的是三种不同的异构：空间切解决同一张图内部算力密度不均，时间切解决请求到达稀疏与长短不一，阶段切解决三个阶段之间算力类型、显存占用、kernel 形态的差异。判断该用哪一种，先问“瓶颈在哪一层”：若瓶颈是单请求内部冗余计算（相似块、相似步），空间切收益最大；若瓶颈是低负载下 batch 填不满，时间切收益最大；若瓶颈是某个阶段把整机拖成空转（典型是 VAE 阶段 GPU 利用率塌陷、文本编码阶段被小 kernel 拖慢），阶段切才是对症的。</p>\n<p>第二根轴是耦合点。连续批处理在单进程内共享 KV/激活，耦合点是调度器的迭代边界；patch 级调度在单请求内共享特征缓存，耦合点是块间依赖；本方法的耦合点是 latent 队列——一个显式的、跨进程甚至跨节点的缓冲。耦合点越显式，解耦越彻底，代价也越硬：队列本身要占显存与网络带宽，且队列深度直接进入端到端时延公式。用前文的流水模型表述，端到端时延由最慢阶段决定：</p>\n<div class=\"formula\">$$T_{\\mathrm{e2e}}=\\max_k\\left(\\frac{Q_k}{\\lambda_k}+T_k^{\\mathrm{svc}}\\right),\\quad \\lambda_k=\\frac{B_k}{T_k^{\\mathrm{svc}}}$$</div>\n<p>这个式子给出一个反直觉的判断：阶段切分并不自动降低时延，它降低的是“阶段间互相绑架”造成的抖动。若某阶段 $T_k^{\\mathrm{svc}}$ 本身就大，拆出来只会让 $Q_k/\\lambda_k$ 这一项显性化。真正被改善的是尾延迟分布——单体部署里 VAE 被去噪 batch 拖着走，P99 被最慢的那次解码拉长；拆开后 VAE 按 tile 并行、按自己的 batch 走，尾部长尾被截断。代价是每次跨阶段传递 latent 都要一次显存拷贝，跨节点时还要过网络，高分辨率 latent 下这笔开销会直接侵蚀吞吐收益。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-46\">四十六 · 决策表：四类候选与适用条件</h3>\n<p>下表把同族候选放在同一张表里对照，列的是“什么条件下选它”，而不是“它有什么特性”。表中不重复各算法自身的机制细节，只标注与本方法的分工边界。</p>\n<table class=\"mini\"><thead><tr><th>候选</th><th>切分维度</th><th>选它的条件</th><th>与本方法的关系</th></tr></thead><tbody>\n<tr><td>单体部署</td><td>不切</td><td>单卡或单机小规模；阶段耗时相近；请求形态单一</td><td>本方法的基线，拆分收益在此时被通信开销吃掉</td></tr>\n<tr><td>连续批处理</td><td>时间（到达）</td><td>请求到达稀疏、长短不一，batch 填不满是主因</td><td>互补：它管到达异构，本方法管阶段异构，可叠加</td></tr>\n<tr><td>patch 级调度</td><td>空间（块）</td><td>单请求内部冗余大（相似块、可跳步），算力密度不均</td><td>正交：可在去噪阶段内部再叠加，不替代阶段切分</td></tr>\n<tr><td>阶段级流水（本方法）</td><td>管线阶段</td><td>阶段资源需求差异大、管线长、SLO 以 P99 达标率为指标</td><td>自身；与上述三者可组合，但组合数受调度器容量约束</td></tr>\n</tbody></table>\n<p>读表的关键是“可叠加但不可互替”。连续批处理叠加在去噪阶段内部，解决的是该阶段 batch 填不满；patch 级调度叠加在去噪阶段内部，解决的是该阶段单请求冗余；两者都不改变“三阶段独立部署”这一层结构。反过来，阶段切分也不能替代批调度——拆开后的每个阶段仍要自己填 batch，否则只是把空转从整机搬到了单个阶段。工程上常见的错误是只做拆分不做阶段内批调度，结果 VAE 阶段因为 tile 并行度不足仍然空转，收益归零。</p>\n<p>还有一个隐含条件常被忽略：阶段数。收益随阶段数增加而增加，但跨节点传输次数也随阶段数线性增加。三阶段（编码/去噪/解码）在同机内拆分，latent 拷贝走显存到显存；一旦编码与解码被挤到不同节点，每次传递都要过网络，高分辨率 latent 的字节数不小，这笔带宽开销会按阶段数累加。因此决策表里“管线长”是收益条件，也是成本条件，两者同向增长，存在一个由网络带宽与 latent 尺寸共同决定的拐点。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-47\">四十七 · 副本弹性：容量公式与调度滞后</h3>\n<p>阶段拆分的第二个直接后果是副本数不再是一个全局量，而是每阶段一个。容量规划按阶段做：</p>\n<div class=\"formula\">$$\\text{Replicas}_{s}\\propto\\frac{\\lambda_{s}\\,\\bar{t}_{s}}{\\text{target util}}$$</div>\n<p>其中 $\\lambda_s$ 是该阶段到达率、$\\bar{t}_s$ 是该阶段平均服务时间。这个式子的工程含义是：三阶段的副本比例应当正比于各自的“到达率×服务时间”，而不是平均分配。文本编码阶段服务时间短、可大批量，副本数少；去噪阶段服务时间长、按分辨率与步数分池，副本数多且池间不共享；VAE 阶段按 tile 并行，单副本内并行度高但显存占用大，副本数受显存约束而非算力约束。硬件档位也因此可以异构：编码用低算力卡、去噪用高算力卡、解码用大显存卡——这是阶段切分相对单体部署最实际的成本优势，单体部署被迫用同一档硬件满足三种截然不同的需求。</p>\n<p>代价落在调度器上。副本弹性意味着冷启动：新副本拉起要加载权重、预热显存池，这段时间内它不贡献吞吐，而队列还在涨。显存碎片则来自反复扩缩导致的分配器状态不整齐，尤其在 VAE 阶段这种大块显存需求下更明显。更棘手的是滞后决策：调度器依据队列深度与 P99 时延扩缩，而这两项指标本身有观测延迟，负载突增时扩缩动作可能落在需求峰值之后，造成一段 SLO 违约窗口。缓解手段不是把调度器做得更灵敏（更灵敏意味着更频繁的扩缩与更多冷启动），而是给队列加背压：上游阶段按下游队列深度限流，过载时按优先级丢弃或降分辨率，把“扩缩滞后”的后果从雪崩降级为可控的降质。</p>\n<p>具体例子：混合分辨率文生图服务，去噪阶段按分辨率分池后，高分辨率池的 $\\bar{t}_s$ 显著大于低分辨率池，若两池共用副本，高分辨率请求会把低分辨率请求的尾延迟一起拖长；分池后各自按上式配副本，低分辨率池可以用小 batch 高副本数压尾延迟，高分辨率池用大 batch 少副本数保吞吐。这就是“按阶段做 batch 与并行策略”在副本层面的落地，也是单体部署做不到的。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-48\">四十八 · 量化与并行的阶段化选择</h3>\n<p>阶段切分让精度与并行策略也可以按阶段选，而不是全管线一刀切。文本编码阶段是中小 GEMM 为主、对精度敏感度相对低，可用 FP8；去噪阶段是 DiT 主体，算力密集且对数值误差在长步数上累积敏感，量化方案要按步数与分辨率分池选（NVFP4 混合精度、FP8 注意力与 GEMM、分块 PTQ 校准这些手段的取舍见同模块其他条目，此处只讲“按阶段选”这一层）；VAE 解码阶段是卷积与上采样为主、显存带宽压力大，量化收益更多体现在显存占用而非算力。三阶段用不同精度，意味着 latent 队列两端要做精度转换，这是一次额外的拷贝与转换开销，必须计入阶段间传输成本。</p>\n<p>并行拓扑同理：阶段内数据并行、阶段间流水。这个组合的代价是流水气泡——当某阶段副本数少而服务时间长时，上下游会被它的节奏卡住，端到端吞吐受最慢阶段节拍约束，这正是前面 $\\max_k$ 公式的另一面。工程判断是：流水拓扑适合阶段服务时间相近或可通过副本数拉平的场景；若某阶段服务时间天然是其他阶段的数倍（典型是高分辨率去噪），则应给该阶段更多副本并允许队列在它前面堆积，用队列深度换节拍匹配，而不是强行让所有阶段同拍。</p>\n<p>系统代价要算清三笔账：latent 传输的显存拷贝与网络开销（跨节点时更明显）、多副本弹性的冷启动与显存碎片、调度器复杂度上升带来的运维成本。第一笔随分辨率与阶段数增长，第二笔随扩缩频率增长，第三笔随阶段数与池数增长。三笔账合起来决定规模上限：队列缓冲容量与调度器容量是硬约束，超过之后增加阶段数不再带来吞吐收益，只带来更多失败模式。</p>\n\n<h3 id=\"alg-stage-serving-pipeline-sec-49\">四十九 · 失败模式的归属判断</h3>\n<p>诊断时先分清失败属于哪一层，再决定换算法还是调参数。队列积压且下游 OOM：这是背压缺失，属于本方法的调度层问题，加背压与优先级丢弃即可，不需要换切分维度。P99 达标率在负载突增时塌陷但稳态正常：这是副本弹性滞后，属于容量层问题，应检查扩缩指标（队列深度与 P99 的观测延迟）与冷启动时间，而不是去改 batch 策略。吞吐提升不及预期且跨节点：这是 latent 传输开销吃掉收益，属于拓扑层问题，应优先把相邻阶段拉回同机，或降低 latent 精度与尺寸，而不是增加阶段数。若单请求内部冗余明显而阶段耗时相近，则本方法本就不该是首选，应回到 patch 级调度。</p>\n<p>一个可操作的归属判据：看“最慢阶段”是否稳定。若 $T_{\\mathrm{e2e}}$ 长期由同一阶段主导且该阶段队列不深，说明是服务时间本身的问题，拆分无益，应在该阶段内部做批调度或空间切分；若主导阶段在不同时刻漂移，说明是阶段间节拍失配，属于流水拓扑问题，应调副本比例而非改算法。这个判据只用队列深度与阶段时延两项指标，不依赖额外埋点，适合在线上直接做。</p>\n<p>最后落在工程判断上：阶段级流水的价值不在“拆”，而在“让每个阶段用自己的 batch、自己的并行、自己的硬件档位跑满”，并把尾延迟从“被最慢阶段绑架”变成“由最慢阶段显性决定、可被背压与副本弹性调节”。当 latent 传输开销低于被解耦出来的空转损失时，拆分是正收益；当跨节点传输把这份开销推高到与空转损失同量级时，正确动作是把阶段拉回同机或退回单体部署加连续批处理，而不是继续增加阶段数。决策表里那条“小规模单卡部署下拆分收益有限”的边界，本质上就是这条开销与损失的比较线。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2025 · 视频与流式生成推理</td></tr><tr><td>解决什么</td><td>文本编码、DiT 去噪、VAE 解码的算力与显存特征差异大，单体部署导致 GPU 在 VAE 阶段空转、在文本编码阶段…</td></tr><tr><td>一句话机制</td><td>把扩散管线拆成编码/去噪/解码三个阶段独立部署，按阶段做 batch 与并行策略，阶段间用 latent 队列解耦，按…</td></tr><tr><td>代价与失效</td><td>阶段间 latent 传输引入额外显存拷贝与网络开销，跨节点时更明显；多副本弹性带来冷启动与显存碎片，调度器复杂度上升</td></tr><tr><td>后继</td><td></td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-stage-serving-pipeline · 共 8 个片段</p>\n";break;}}})();
